-- Lesson content rewrite: c_netplus_d1, c_netplus_d2, c_netplus_d3, c_netplus_d4, c_netplus_d5
-- New slide format (terms at a glance, examples, comparisons, diagrams,
-- practice questions). Title slides kept; mini-exam questions untouched.
-- Safe to re-run: the current content is backed up once first.

create table if not exists lesson_content_backup (
  lesson_id uuid not null, content_blocks jsonb not null,
  backed_up_at timestamptz not null default now(), note text);
alter table lesson_content_backup enable row level security;

insert into lesson_content_backup (lesson_id, content_blocks, note)
select id, content_blocks, 'before content rewrite (c_netplus_d1, c_netplus_d2, c_netplus_d3, c_netplus_d4, c_netplus_d5)' from lessons where id in ('66827abe-31b8-45fd-833c-9bc5dbfad7d6', 'e7703cd8-1777-475f-b5be-626bf9d2a64e', '14193f44-6153-432a-9e40-cf14d5698519', '77558548-52c0-4e7a-ac84-b9b83ff4120b', '81282d03-be25-42cf-af32-fea46bd9cbce', '1c177ebe-314e-4561-a549-9cd8b839cda2', '7adaf102-02ab-4ed9-a0a3-2aa987578fdc', '0e171b0b-cfbc-4706-9232-5ce187189638', '3812675b-c221-410e-9b4f-094b2a19d6eb', 'b6ef6e8b-39f9-4a0b-9e1e-77696f538cd9', 'fb12b858-5660-4647-b3a1-580a204ba272', '5be06466-f0b4-472d-b570-9420ed932f62', '92b302c0-7557-41f3-836f-917e344cb9bb', 'b903ed18-cea7-4a4c-9eb3-49fbcc70030c', 'b6ac3f57-475f-49cb-b2d8-930c48e02b49', '04ad67f0-64ab-4756-bd44-a751cdc951fe', 'a9b92195-f33a-4656-9b83-6c49903fbe59', '71a9ce22-66de-4103-adbb-488759f4b00a', '5a4064bc-2cea-40b2-bba6-f918a5956620', '491dd58a-275c-4304-bd18-07f655a08e2e', '63042c20-aafa-4a9b-8cf1-d668905f21fa', '69856dee-0686-4a7c-aa5e-5d913ae5b763', '874b400a-9212-483b-9620-32a2b52457cb', '6acfa0ae-5228-4176-b84f-e5a095afced4', 'e4738f97-69dc-4fad-ab09-9b002ff8e035', 'cd8e19ce-d9c8-45fc-9ac7-4569cabd949d', 'd5bedaf9-add9-453b-8c0f-a3d43d13dc5e', 'e57e0fca-7fac-415e-bb33-38516943c69f', '4da7098d-9b84-4fcb-bd2b-2458a54f0303', 'c64b2918-bb2c-4cad-a777-2a8a7b20f4e3', '7629923f-1b15-443b-9edf-3426b4526b15', '1c6fc27a-5f23-4474-a8f1-4d11045dba5c', '7ce72855-8306-4d8c-bdf3-4cc7766aaeab', '4946eea7-023a-4d9c-a8fe-4fa994b52565', '8ac95301-3728-4231-ab37-e7d8c9bc7de2', '5d7d3a57-f0b4-4cf2-9c8f-93e980a6767a', 'a86c871d-a6cd-4366-8116-c1e27fdcc9a2', 'ee19b5d9-a650-4860-8cb9-a639bd9afbcd', '2331729e-c44c-4f7d-99fc-c20bf2a1d605', 'd4adb8fc-02d5-440b-ad76-d8dbc2759ef4', '97fa3df7-b8ac-4d0b-b147-20d49b255250')
  and not exists (select 1 from lesson_content_backup b where b.lesson_id = lessons.id and b.note = 'before content rewrite (c_netplus_d1, c_netplus_d2, c_netplus_d3, c_netplus_d4, c_netplus_d5)');

-- What the Network+ Exam Actually Tests
update lessons set content_blocks = '[{"text": "What the Network+ Exam Actually Tests", "type": "title", "overview": "A map of the five domains covered in this course, and how CompTIA actually scores the N10-009 exam.", "examContext": "Why this matters: domain weights tell you where to put your study time before you spend a single hour on content."}, {"type": "term_set", "heading": "The exam at a glance", "terms": [{"term": "Exam", "short": "CompTIA Network+ N10-009."}, {"term": "Length", "short": "Up to 90 questions in 90 minutes."}, {"term": "Question types", "short": "Multiple choice plus performance-based questions (PBQs)."}, {"term": "Passing score", "short": "720 on a 100 to 900 scale."}]}, {"type": "compare", "heading": "The five domains and their weight", "columns": ["Weight"], "rows": [{"label": "1. Networking Concepts", "values": ["23%"]}, {"label": "2. Network Implementation", "values": ["20%"]}, {"label": "3. Network Operations", "values": ["19%"]}, {"label": "4. Network Security", "values": ["14%"]}, {"label": "5. Network Troubleshooting", "values": ["24%, the largest"]}]}, {"type": "key_term", "term": "Performance-based question (PBQ)", "definition": "An interactive task that tests whether you can do something, not just recognize a term.", "example": "You''re given a /24 and four departments with different host counts, and you drag the right subnet to each one."}, {"type": "callout", "variant": "tip", "text": "Concepts and Troubleshooting together are nearly half your score. Troubleshooting thinking shows up even inside questions about other domains."}]'::jsonb where id = '66827abe-31b8-45fd-833c-9bc5dbfad7d6';

-- How to Use Orivian
update lessons set content_blocks = '[{"text": "How to Use Orivian", "type": "title", "overview": "How a domain''s lessons, recap, and checkpoint fit together, and what it takes to mark a lesson complete.", "examContext": "Why this matters: understanding the platform''s rhythm up front means you spend your time studying, not figuring out the interface."}, {"type": "paragraph", "text": "Every domain in this course follows the same pattern. Learn it once and you know it everywhere."}, {"type": "diagram", "heading": "Inside a domain", "diagram": {"kind": "flow", "steps": [{"label": "Lessons", "note": "Each lesson ends in a 10-question mini-exam. 80% to pass; retake as often as you like."}, {"label": "Domain recap", "note": "The highest-yield facts from every lesson, plus rapid practice questions. No exam."}, {"label": "Domain checkpoint", "note": "A longer exam across the whole domain, with fresh scenarios. The real test of whether it stuck."}]}}, {"type": "term_set", "heading": "How a lesson is laid out", "terms": [{"term": "Key terms at a glance", "short": "Every term with a one-line definition, often next to a diagram."}, {"term": "Breakdown", "short": "Terms in depth, each with an \"In practice\" example."}, {"term": "Side by side", "short": "Comparison tables for the pairs the exam loves, with an exam cue row."}, {"term": "How this shows up on the exam", "short": "Practice questions: pick an answer, then see why it''s right and what the trap was. Not scored."}, {"term": "Mini-exam", "short": "The graded questions at the end. You can review every past attempt afterwards."}]}, {"type": "term_set", "heading": "Finding your way", "terms": [{"term": "The trail map", "short": "Each course page shows your path as a trail: covered ground in green, your next waypoint in gold."}, {"term": "Next waypoint", "short": "The card at the top of the course page always points to your next step."}, {"term": "Study timer", "short": "Counts only while a lesson or exam is visible in front of you. For your awareness; never graded."}, {"term": "Listen", "short": "Any slide can be read aloud. Turn on auto-play in Voice settings to hear each slide as you press Next."}, {"term": "Keyboard", "short": "Arrow keys move between slides, L listens, N opens notes."}]}, {"type": "term_set", "heading": "Your notes", "terms": [{"term": "Write a note", "short": "Open Notes in any lesson and type; it''s linked to that lesson automatically."}, {"term": "Save to notes", "short": "Select any sentence in a lesson and tap Save to notes to keep it as a quote."}, {"term": "My Notes", "short": "Everything you''ve saved, on the Notes page, grouped by course and lesson."}], "intro": "Notes are private to you and follow your account to any device."}, {"type": "callout", "variant": "tip", "text": "One or two lessons done attentively beat a skimmed marathon. Use the recap right before the checkpoint."}]'::jsonb where id = 'e7703cd8-1777-475f-b5be-626bf9d2a64e';

-- A Study Strategy That Works
update lessons set content_blocks = '[{"text": "A Study Strategy That Works", "type": "title", "overview": "A short, practical approach to pacing your study time and retaining what you read.", "examContext": "Why this matters: Network+ leans harder on hands-on scenario reasoning (subnetting, cable/connector identification, troubleshooting flow) than on pure definitions, how you study needs to match that."}, {"type": "paragraph", "text": "The most common Network+ mistake is treating it like a vocabulary test. Troubleshooting and Concepts make up nearly half the exam, and both are scenario driven. You need to apply what you know, not just recite it."}, {"type": "term_set", "heading": "How to study", "terms": [{"term": "Actually practice subnetting", "short": "Work problems until splitting a network is fast and automatic. It appears across several domains."}, {"term": "Recap as spaced repetition", "short": "Revisit the domain recap a few days after the lessons, right before the checkpoint."}, {"term": "Think like a technician on a call", "short": "Most questions describe symptoms and ask what you''d check first."}]}, {"type": "diagram", "heading": "The troubleshooting order you''ll use everywhere", "diagram": {"kind": "flow", "steps": [{"label": "Identify the problem"}, {"label": "Establish a theory"}, {"label": "Test the theory"}, {"label": "Act on it"}]}, "caption": "Many wrong answers are valid fixes for the wrong step. Domain 5 covers the full seven-step method."}, {"type": "scenario", "prompt": "A user reports they can''t reach the internet. What should a technician do **first**?", "choices": [{"id": "a", "text": "Replace the user''s network cable"}, {"id": "b", "text": "Gather information: ask what changed and check what the user sees"}, {"id": "c", "text": "Reboot the core router"}, {"id": "d", "text": "Reinstall the network driver"}], "answer": "b", "why": "Identifying the problem comes first: question the user, gather symptoms, ask what changed.", "trap": "Replacing parts may even fix it, but acting before identifying the problem skips the methodology."}, {"type": "callout", "variant": "tip", "text": "When a question gives symptoms, decide which troubleshooting step it''s asking about before reading the choices."}]'::jsonb where id = '14193f44-6153-432a-9e40-cf14d5698519';

-- OSI Model Layers and Encapsulation
update lessons set content_blocks = '[{"text": "OSI Model Layers and Encapsulation", "type": "title", "overview": "The seven-layer OSI reference model, what each layer is responsible for, and how data gets wrapped (encapsulated) and unwrapped (de-encapsulated) as it travels.", "examContext": "Heavily tested as \"which layer handles X\" and \"what is this PDU called at layer Y\", know the layer order and each layer''s job cold."}, {"type": "diagram", "heading": "The OSI model", "diagram": {"kind": "ladder", "rungs": [{"label": "7 Application", "note": "User-facing protocols: HTTP, DNS, SMTP."}, {"label": "6 Presentation", "note": "Formatting, encryption, compression."}, {"label": "5 Session", "note": "Opens, manages and closes sessions."}, {"label": "4 Transport", "note": "End-to-end delivery and ports: TCP, UDP."}, {"label": "3 Network", "note": "Logical addressing and routing: IP, routers."}, {"label": "2 Data link", "note": "MAC addressing on the local segment: switches."}, {"label": "1 Physical", "note": "Bits on the wire or air: cables, radios, hubs."}], "top": "closest to the user", "bottom": "closest to the wire"}, "caption": "Mnemonic, top down: All People Seem To Need Data Processing."}, {"type": "compare", "heading": "The PDU at each layer", "columns": ["PDU name", "Header adds"], "rows": [{"label": "Layer 4 Transport", "values": ["Segment (TCP) or datagram (UDP)", "Source and destination ports"]}, {"label": "Layer 3 Network", "values": ["Packet", "Source and destination IP addresses"]}, {"label": "Layer 2 Data link", "values": ["Frame", "Source and destination MAC addresses"]}, {"label": "Layer 1 Physical", "values": ["Bits", "Nothing; it''s signals"]}], "intro": "Encapsulation wraps data going down the stack; the receiver strips each header going back up."}, {"type": "compare", "heading": "Which device works at which layer", "columns": ["Hub", "Switch", "Router"], "rows": [{"label": "Layer", "values": ["1", "2", "3"]}, {"label": "Forwards by", "values": ["Nothing; repeats to every port", "MAC address", "IP address"]}]}, {"type": "scenario", "prompt": "At which layer would you troubleshoot a problem with MAC address tables?", "choices": [{"id": "a", "text": "Layer 1"}, {"id": "b", "text": "Layer 2"}, {"id": "c", "text": "Layer 3"}, {"id": "d", "text": "Layer 4"}], "answer": "b", "why": "MAC addresses live at the data link layer."}, {"type": "scenario", "prompt": "A packet capture shows a unit containing source and destination IP addresses. What is this unit called?", "choices": [{"id": "a", "text": "Frame"}, {"id": "b", "text": "Segment"}, {"id": "c", "text": "Packet"}, {"id": "d", "text": "Bits"}], "answer": "c", "why": "IP addressing is added at layer 3, where the PDU is a packet.", "trap": "A frame adds MAC addresses, and it contains the packet, but the IP header belongs to the packet."}, {"type": "callout", "variant": "tip", "text": "Hub is layer 1, switch is layer 2 by MAC, router is layer 3 by IP. Segment, packet, frame, bits on the way down."}]'::jsonb where id = '77558548-52c0-4e7a-ac84-b9b83ff4120b';

-- Networking Appliances and Their Functions
update lessons set content_blocks = '[{"text": "Networking Appliances and Their Functions", "type": "title", "overview": "The core devices that make up a network, what each one is for, and how to tell similar-sounding devices apart.", "examContext": "Expect \"which device would you use to...\" scenario questions that require distinguishing between similar devices (e.g., a proxy vs. a load balancer vs. a firewall)."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Switch", "short": "Forwards frames inside a LAN using its MAC table. Layer 3 switches can also route."}, {"term": "Router", "short": "Forwards packets between networks using IP routing tables."}, {"term": "Bridge", "short": "Older layer 2 device joining two segments; essentially a two-port switch."}, {"term": "Access point", "short": "Bridges wireless clients onto the wired network; standalone or controller managed."}, {"term": "Firewall", "short": "Filters by rules; next-generation firewalls add application awareness."}, {"term": "IDS / IPS", "short": "Detects and alerts / sits inline and blocks."}, {"term": "Load balancer", "short": "Spreads client requests across several servers."}]}, {"type": "compare", "heading": "Forward vs. reverse proxy", "columns": ["Forward proxy", "Reverse proxy"], "rows": [{"label": "Acts on behalf of", "values": ["Internal clients going out", "Internal servers being reached"]}, {"label": "Sits", "values": ["Between users and the internet", "In front of web servers"]}, {"label": "Typical uses", "values": ["Filtering, caching", "Load balancing, TLS termination"]}], "cue": ["\"Users browsing out\"", "\"Clients reaching our servers\""]}, {"type": "key_term", "term": "Load balancer", "definition": "Distributes incoming requests across a pool of servers for performance and availability.", "example": "Three web servers sit behind a load balancer; when one fails its health check, traffic flows to the other two."}, {"type": "scenario", "prompt": "A company wants all employee web traffic to pass through one device that filters sites and caches common pages. What should it deploy?", "choices": [{"id": "a", "text": "Reverse proxy"}, {"id": "b", "text": "Forward proxy"}, {"id": "c", "text": "Load balancer"}, {"id": "d", "text": "Bridge"}], "answer": "b", "why": "A forward proxy acts for internal clients reaching out."}, {"type": "scenario", "prompt": "Which device can actively block malicious traffic it detects?", "choices": [{"id": "a", "text": "IDS"}, {"id": "b", "text": "IPS"}, {"id": "c", "text": "Hub"}, {"id": "d", "text": "Bridge"}], "answer": "b", "why": "An IPS sits inline and can drop traffic; an IDS only alerts."}, {"type": "callout", "variant": "tip", "text": "Direction tells you the proxy: clients going out is forward, servers being reached is reverse."}]'::jsonb where id = '81282d03-be25-42cf-af32-fea46bd9cbce';

-- Cloud Concepts and Connectivity Options
update lessons set content_blocks = '[{"text": "Cloud Concepts and Connectivity Options", "type": "title", "overview": "Cloud service and deployment models, and the specific technologies used to connect an on-premises network to a cloud provider.", "examContext": "Expect questions naming a scenario and asking which service model or connectivity option fits, plus responsibility questions about what the provider vs. customer manages."}, {"type": "diagram", "heading": "Cloud service models", "diagram": {"kind": "pyramid", "tiers": [{"label": "SaaS", "note": "Provider runs everything; you use the application and manage your data and access."}, {"label": "PaaS", "note": "Provider also runs the OS and runtime; you deploy code."}, {"label": "IaaS", "note": "Provider supplies compute, storage and network; you manage the OS up."}], "top": "provider manages most", "bottom": "customer manages most"}}, {"type": "term_set", "heading": "Deployment models", "terms": [{"term": "Public", "short": "Shared, multi-tenant, provider owned."}, {"term": "Private", "short": "Dedicated to one organization."}, {"term": "Hybrid", "short": "On premises and cloud integrated."}, {"term": "Community", "short": "Shared by organizations with common requirements."}]}, {"type": "compare", "heading": "Connecting to the cloud", "columns": ["VPN over the internet", "Direct connection"], "rows": [{"label": "Path", "values": ["Encrypted tunnel across the internet", "Private circuit to the provider"]}, {"label": "Performance", "values": ["Varies with the internet", "Consistent bandwidth and latency"]}, {"label": "Cost", "values": ["Cheapest", "More expensive"]}], "intro": "Multi-cloud uses more than one provider to avoid lock-in or a single point of failure."}, {"type": "key_term", "term": "SDN", "definition": "Software-defined networking separates the control plane, which decides where traffic goes, from the data plane, which forwards it. Control becomes central and programmable.", "example": "An administrator changes one policy in the SDN controller and every switch updates its forwarding behavior."}, {"type": "scenario", "prompt": "Developers want to deploy code without managing servers or operating systems. Which model fits?", "choices": [{"id": "a", "text": "IaaS"}, {"id": "b", "text": "PaaS"}, {"id": "c", "text": "SaaS"}, {"id": "d", "text": "On premises"}], "answer": "b", "why": "PaaS handles the OS and runtime; customers bring code."}, {"type": "scenario", "prompt": "A trading firm needs predictable, low latency links to its cloud provider that avoid the public internet. What should it use?", "choices": [{"id": "a", "text": "Site-to-site VPN"}, {"id": "b", "text": "Direct dedicated connection"}, {"id": "c", "text": "Community cloud"}, {"id": "d", "text": "Multi-cloud"}], "answer": "b", "why": "A dedicated connection bypasses the internet for consistent performance."}, {"type": "callout", "variant": "tip", "text": "IaaS, PaaS, SaaS: the provider takes on more at each step. VPN is cheap and variable; a direct link is consistent and costly."}]'::jsonb where id = '1c177ebe-314e-4561-a549-9cd8b839cda2';

-- Common Ports and Protocols
update lessons set content_blocks = '[{"text": "Common Ports and Protocols", "type": "title", "overview": "The most heavily tested port numbers, which transport protocol each uses, and what each service actually does.", "examContext": "Port memorization is one of the highest-yield things you can do for this exam, matching questions and scenario questions both depend on it directly."}, {"type": "compare", "heading": "Web, file transfer and remote access", "columns": ["Port", "Transport", "Notes"], "rows": [{"label": "FTP", "values": ["20, 21", "TCP", "Data and control; unencrypted"]}, {"label": "SSH / SFTP", "values": ["22", "TCP", "Encrypted shell and file transfer"]}, {"label": "Telnet", "values": ["23", "TCP", "Unencrypted shell; insecure"]}, {"label": "HTTP", "values": ["80", "TCP", "Unencrypted web"]}, {"label": "HTTPS", "values": ["443", "TCP", "Web over TLS"]}, {"label": "FTPS", "values": ["989, 990", "TCP", "FTP over TLS"]}, {"label": "RDP", "values": ["3389", "TCP", "Windows Remote Desktop"]}]}, {"type": "compare", "heading": "Email", "columns": ["Port", "Notes"], "rows": [{"label": "SMTP", "values": ["25", "Server to server sending"]}, {"label": "SMTP submission", "values": ["587", "Authenticated client sending"]}, {"label": "POP3", "values": ["110", "Download and usually remove from server"]}, {"label": "IMAP", "values": ["143", "Keep mail synced on the server"]}]}, {"type": "compare", "heading": "Infrastructure and directory", "columns": ["Port", "Transport", "Notes"], "rows": [{"label": "DNS", "values": ["53", "UDP and TCP", "UDP for queries; TCP for zone transfers"]}, {"label": "DHCP", "values": ["67, 68", "UDP", "67 server, 68 client"]}, {"label": "TFTP", "values": ["69", "UDP", "No authentication; firmware and configs"]}, {"label": "NTP", "values": ["123", "UDP", "Time sync"]}, {"label": "SNMP", "values": ["161, 162", "UDP", "161 queries, 162 traps"]}, {"label": "LDAP / LDAPS", "values": ["389 / 636", "TCP", "Directory queries / over TLS"]}, {"label": "Syslog", "values": ["514", "UDP", "Log forwarding"]}]}, {"type": "scenario", "prompt": "A firewall must allow DNS zone transfers between two name servers. Which port and protocol?", "choices": [{"id": "a", "text": "UDP 53"}, {"id": "b", "text": "TCP 53"}, {"id": "c", "text": "UDP 69"}, {"id": "d", "text": "TCP 389"}], "answer": "b", "why": "Zone transfers use TCP 53; ordinary queries use UDP 53.", "trap": "Knowing 53 isn''t enough. Questions about a dual-protocol port test which transport applies."}, {"type": "scenario", "prompt": "A user wants email to stay on the server so it appears on her phone and laptop. Which protocol should she use?", "choices": [{"id": "a", "text": "POP3"}, {"id": "b", "text": "IMAP"}, {"id": "c", "text": "SMTP"}, {"id": "d", "text": "SNMP"}], "answer": "b", "why": "IMAP keeps mail synced on the server."}, {"type": "callout", "variant": "tip", "text": "When a port has two numbers or two transports, the question is testing which side or which transport, not just the number."}]'::jsonb where id = '7adaf102-02ab-4ed9-a0a3-2aa987578fdc';

-- Naming, Time, and Management Protocols
update lessons set content_blocks = '[{"text": "Naming, Time, and Management Protocols", "type": "title", "overview": "The mechanics behind DNS resolution, the DHCP lease process, time synchronization, and device monitoring/directory protocols.", "examContext": "Scenario questions often describe a broken DNS lookup, an expired DHCP lease, or a clock-drift issue and ask you to identify the protocol and failure point."}, {"type": "diagram", "heading": "DNS resolution", "diagram": {"kind": "flow", "steps": [{"label": "Local cache", "note": "The client checks what it already knows."}, {"label": "Recursive resolver", "note": "ISP or public resolver does the legwork."}, {"label": "Root server", "note": "Points to the right TLD."}, {"label": "TLD server", "note": "For example .com; points to the domain."}, {"label": "Authoritative server", "note": "Returns the actual record."}]}}, {"type": "compare", "heading": "DNS record types", "columns": ["Holds"], "rows": [{"label": "A", "values": ["IPv4 address"]}, {"label": "AAAA", "values": ["IPv6 address"]}, {"label": "CNAME", "values": ["Alias to another name"]}, {"label": "MX", "values": ["Mail server for the domain"]}, {"label": "TXT", "values": ["Free text, often SPF or verification"]}, {"label": "NS", "values": ["Authoritative name server"]}, {"label": "PTR", "values": ["Reverse lookup, IP to name"]}]}, {"type": "diagram", "heading": "DHCP lease: DORA", "diagram": {"kind": "flow", "steps": [{"label": "Discover", "note": "Client broadcasts for a server."}, {"label": "Offer", "note": "Server offers a configuration."}, {"label": "Request", "note": "Client asks for that offer."}, {"label": "Acknowledge", "note": "Server confirms the lease."}]}}, {"type": "key_term", "term": "DHCP relay (IP helper)", "definition": "A router forwards DHCP broadcasts to a server on another subnet, because broadcasts don''t cross routers.", "example": "A new VLAN''s clients get APIPA addresses until the router interface gets an ip helper-address pointing to the DHCP server."}, {"type": "term_set", "heading": "Time and management", "terms": [{"term": "NTP", "short": "Keeps clocks in sync; vital for logs, certificates and Kerberos."}, {"term": "SNMP", "short": "GET queries devices; traps push alerts. v3 adds authentication and encryption."}, {"term": "LDAP", "short": "Queries and modifies directories such as Active Directory."}]}, {"type": "scenario", "prompt": "Users on a newly created subnet can''t get IP addresses, while the DHCP server on another subnet works fine for everyone else. What''s the most likely fix?", "choices": [{"id": "a", "text": "Add a PTR record"}, {"id": "b", "text": "Configure a DHCP relay on the router"}, {"id": "c", "text": "Change the NTP server"}, {"id": "d", "text": "Enable SNMP traps"}], "answer": "b", "why": "Discover broadcasts aren''t reaching the server across the router."}, {"type": "scenario", "prompt": "Kerberos logins start failing across a site, and the domain controller''s clock is found to be 20 minutes off. Which protocol needs attention?", "choices": [{"id": "a", "text": "SNMP"}, {"id": "b", "text": "NTP"}, {"id": "c", "text": "LDAP"}, {"id": "d", "text": "DNS"}], "answer": "b", "why": "Kerberos rejects requests with too much clock drift; NTP keeps clocks aligned."}, {"type": "callout", "variant": "tip", "text": "DORA in order. Stuck without an address usually means a DORA step failed; another subnet means check the relay."}]'::jsonb where id = '0e171b0b-cfbc-4706-9232-5ce187189638';

-- Transmission Media and Transceivers
update lessons set content_blocks = '[{"text": "Transmission Media and Transceivers", "type": "title", "overview": "Copper cable categories, fiber types, common connectors, and the transceiver modules that plug into networking equipment.", "examContext": "Very testable as matching/identification questions, know which cable category supports which speed, and single-mode vs. multi-mode fiber use cases."}, {"type": "compare", "heading": "Copper categories", "columns": ["Top speed", "Distance"], "rows": [{"label": "Cat 5e", "values": ["1 Gbps", "100 m"]}, {"label": "Cat 6", "values": ["10 Gbps to 55 m; 1 Gbps to 100 m", "100 m"]}, {"label": "Cat 6a", "values": ["10 Gbps", "100 m"]}, {"label": "Cat 8", "values": ["40 Gbps", "30 m, data centers"]}], "intro": "**STP** adds shielding against electromagnetic interference; **UTP** doesn''t."}, {"type": "compare", "heading": "Single-mode vs. multimode fiber", "columns": ["Single-mode (SMF)", "Multimode (MMF)"], "rows": [{"label": "Core", "values": ["Narrow, one light path", "Wider, many light paths"]}, {"label": "Distance", "values": ["Kilometers", "Hundreds of meters"]}, {"label": "Cost", "values": ["Higher", "Lower"]}, {"label": "Typical use", "values": ["Backbone and WAN runs", "Inside buildings and data centers"]}], "cue": ["\"Kilometers\" or \"between campuses\"", "\"Within the data center\""]}, {"type": "term_set", "heading": "Connectors and transceivers", "terms": [{"term": "LC", "short": "Small form factor; the most common fiber connector today."}, {"term": "SC / ST", "short": "Square push-pull / older twist-lock."}, {"term": "SFP / SFP+", "short": "Pluggable transceiver, typically 1 Gbps / 10 Gbps."}, {"term": "QSFP", "short": "Quad SFP, 40 Gbps and up, for core switching."}], "intro": "Transceivers must match the fiber type and each other at both ends."}, {"type": "key_term", "term": "Crosstalk", "definition": "A signal on one wire pair bleeding into the neighboring pair. The twists in twisted pair exist to reduce it.", "example": "A badly terminated cable with untwisted pairs at the jack passes a basic test but shows errors at gigabit speed."}, {"type": "scenario", "prompt": "Two buildings 8 km apart need a high-speed link. Which medium fits?", "choices": [{"id": "a", "text": "Cat 6a"}, {"id": "b", "text": "Multimode fiber"}, {"id": "c", "text": "Single-mode fiber"}, {"id": "d", "text": "Cat 8"}], "answer": "c", "why": "Kilometer distances call for single-mode fiber."}, {"type": "scenario", "prompt": "A new 10 Gbps fiber link won''t come up. One end has a single-mode SFP+ and the other a multimode SFP+. What''s wrong?", "choices": [{"id": "a", "text": "Crosstalk"}, {"id": "b", "text": "Mismatched transceivers"}, {"id": "c", "text": "Wrong copper category"}, {"id": "d", "text": "Missing DHCP relay"}], "answer": "b", "why": "Both ends must match each other and the fiber type."}, {"type": "callout", "variant": "tip", "text": "Kilometers means single-mode. Full 10 Gbps at 100 m means Cat 6a. Mismatched transceivers keep a link down."}]'::jsonb where id = '3812675b-c221-410e-9b4f-094b2a19d6eb';

-- Network Topologies and Architectures
update lessons set content_blocks = '[{"text": "Network Topologies and Architectures", "type": "title", "overview": "How networks are physically/logically arranged, from simple topologies to modern data center architectures.", "examContext": "Expect diagram-style or descriptive scenario questions asking you to name the topology or architecture being described."}, {"type": "compare", "heading": "Basic topologies", "columns": ["Layout", "Weakness"], "rows": [{"label": "Star", "values": ["Everything connects to a central switch", "Central point is a single point of failure"]}, {"label": "Mesh", "values": ["Many or all devices interconnect", "Costly to scale; partial mesh links only critical nodes"]}, {"label": "Bus", "values": ["Everyone shares one cable", "One break affects the segment; legacy"]}, {"label": "Ring", "values": ["Each device links to two neighbors", "Rare today outside fiber rings"]}, {"label": "Hybrid", "values": ["A mix, such as a star of stars", "More complex"]}]}, {"type": "compare", "heading": "Data center architectures", "columns": ["Three-tier", "Collapsed core", "Spine-leaf"], "rows": [{"label": "Layers", "values": ["Core, distribution, access", "Core and distribution merged, plus access", "Spine and leaf"]}, {"label": "Fits", "values": ["Traditional enterprise", "Smaller networks", "Modern data centers"]}, {"label": "Rule to spot it", "values": ["Three distinct tiers", "Two tiers", "Every leaf to every spine, nothing else"]}]}, {"type": "key_term", "term": "East-west vs. north-south traffic", "definition": "East-west moves between servers inside the data center; north-south moves in and out of it. Spine-leaf is built for heavy east-west traffic.", "example": "A web server querying its database server is east-west. A customer loading the site is north-south."}, {"type": "scenario", "prompt": "Every access switch connects to every core switch, and no access switch connects to another. What architecture is this?", "choices": [{"id": "a", "text": "Three-tier"}, {"id": "b", "text": "Spine-leaf"}, {"id": "c", "text": "Full mesh"}, {"id": "d", "text": "Ring"}], "answer": "b", "why": "That exact pattern defines spine-leaf, whatever the switches are called."}, {"type": "scenario", "prompt": "Which topology is most common in office LANs but fails entirely if its central device fails?", "choices": [{"id": "a", "text": "Mesh"}, {"id": "b", "text": "Bus"}, {"id": "c", "text": "Star"}, {"id": "d", "text": "Ring"}], "answer": "c", "why": "A star depends on its central switch."}, {"type": "callout", "variant": "tip", "text": "Spine-leaf: every leaf to every spine, nothing else. Server to server is east-west."}]'::jsonb where id = 'b6ef6e8b-39f9-4a0b-9e1e-77696f538cd9';

-- IPv4 Addressing Fundamentals
update lessons set content_blocks = '[{"text": "IPv4 Addressing Fundamentals", "type": "title", "overview": "How IPv4 addresses are structured, the private address ranges, and CIDR notation, the foundation subnetting builds on.", "examContext": "You must be fluent in recognizing private vs. public ranges and converting between CIDR notation and dotted-decimal subnet masks before subnetting math makes sense."}, {"type": "compare", "heading": "Private ranges (RFC 1918)", "columns": ["Range", "Old class"], "rows": [{"label": "10.0.0.0/8", "values": ["10.0.0.0 to 10.255.255.255", "A"]}, {"label": "172.16.0.0/12", "values": ["172.16.0.0 to 172.31.255.255", "B"]}, {"label": "192.168.0.0/16", "values": ["192.168.0.0 to 192.168.255.255", "C"]}], "intro": "Private addresses aren''t routable on the internet; they need NAT to get out."}, {"type": "compare", "heading": "CIDR to mask", "columns": ["Mask", "Addresses"], "rows": [{"label": "/8", "values": ["255.0.0.0", "16,777,216"]}, {"label": "/16", "values": ["255.255.0.0", "65,536"]}, {"label": "/24", "values": ["255.255.255.0", "256 (254 usable)"]}], "intro": "The CIDR number is how many of the 32 bits are network bits. The first address is the network address and the last is broadcast; neither goes to a host."}, {"type": "key_term", "term": "APIPA", "definition": "Automatic private IP addressing, 169.254.0.0/16. A Windows host assigns itself one when it can''t reach a DHCP server.", "example": "A laptop shows 169.254.33.7 and can''t reach anything. Check the DHCP server and the path to it, not the router."}, {"type": "key_term", "term": "Loopback", "definition": "127.0.0.1 (the whole 127.0.0.0/8 range) always means this host. Used to test the local network stack.", "example": "Pinging 127.0.0.1 succeeds, so the TCP/IP stack is fine and the problem is further out."}, {"type": "scenario", "prompt": "A workstation has the address 169.254.10.20. What''s the most likely problem?", "choices": [{"id": "a", "text": "A bad default gateway"}, {"id": "b", "text": "It couldn''t reach a DHCP server"}, {"id": "c", "text": "A DNS failure"}, {"id": "d", "text": "A duplicate IP address"}], "answer": "b", "why": "169.254 is APIPA, a self-assigned address used when DHCP fails."}, {"type": "scenario", "prompt": "Which address is private?", "choices": [{"id": "a", "text": "172.32.1.1"}, {"id": "b", "text": "172.20.5.9"}, {"id": "c", "text": "192.169.1.1"}, {"id": "d", "text": "11.0.0.1"}], "answer": "b", "why": "172.16.0.0 to 172.31.255.255 is private; 172.20 falls inside.", "trap": "172.32 is just outside the range, a favorite distractor."}, {"type": "callout", "variant": "tip", "text": "169.254 means DHCP failed. 172.16 to 172.31 is private; 172.32 isn''t."}]'::jsonb where id = 'fb12b858-5660-4647-b3a1-580a204ba272';

-- Subnetting in Practice
update lessons set content_blocks = '[{"text": "Subnetting in Practice", "type": "title", "overview": "Hands-on subnetting: how to divide a network into smaller subnets, calculate ranges, and use VLSM to avoid wasting addresses.", "examContext": "This is one of the most heavily practiced PBQ-style skills on the real exam, the goal here is fluency, not just recognizing the rule."}, {"type": "paragraph", "text": "Borrowing host bits creates subnets. Each borrowed bit doubles the number of subnets and halves the hosts in each. Usable hosts are **2 to the power of the host bits, minus 2**, for the network and broadcast addresses."}, {"type": "compare", "heading": "Splitting 192.168.1.0/24", "columns": ["Mask", "Subnets", "Addresses each", "Usable hosts"], "rows": [{"label": "/24", "values": ["255.255.255.0", "1", "256", "254"]}, {"label": "/25", "values": ["255.255.255.128", "2", "128", "126"]}, {"label": "/26", "values": ["255.255.255.192", "4", "64", "62"]}, {"label": "/27", "values": ["255.255.255.224", "8", "32", "30"]}, {"label": "/28", "values": ["255.255.255.240", "16", "16", "14"]}, {"label": "/30", "values": ["255.255.255.252", "64", "4", "2"]}]}, {"type": "key_term", "term": "Block size shortcut", "definition": "256 minus the last non-255 octet of the mask gives the step between subnets.", "example": "A /26 mask ends in 192. 256 minus 192 is 64, so subnets start at .0, .64, .128 and .192."}, {"type": "key_term", "term": "VLSM", "definition": "Variable length subnet masking: different mask lengths in the same network, so small subnets don''t waste addresses.", "example": "A point-to-point router link gets a /30 with two usable addresses, while the user VLAN gets a /25."}, {"type": "scenario", "prompt": "A department needs 50 hosts. What is the smallest subnet that fits?", "choices": [{"id": "a", "text": "/27"}, {"id": "b", "text": "/26"}, {"id": "c", "text": "/25"}, {"id": "d", "text": "/28"}], "answer": "b", "why": "A /26 gives 62 usable hosts. A /27 gives only 30."}, {"type": "scenario", "prompt": "Which subnet does host 192.168.1.140/26 belong to?", "choices": [{"id": "a", "text": "192.168.1.64"}, {"id": "b", "text": "192.168.1.128"}, {"id": "c", "text": "192.168.1.192"}, {"id": "d", "text": "192.168.1.0"}], "answer": "b", "why": "Block size 64: subnets at .0, .64, .128, .192. 140 falls between 128 and 191."}, {"type": "callout", "variant": "tip", "text": "Practice both directions: hosts needed to mask, and mask to usable hosts. The block size shortcut beats binary under time pressure."}]'::jsonb where id = '5be06466-f0b4-472d-b570-9420ed932f62';

-- Evolving Network Environments
update lessons set content_blocks = '[{"text": "Evolving Network Environments", "type": "title", "overview": "Modern shifts in networking: software-defined approaches, automated infrastructure, and zero trust security models.", "examContext": "This objective is newer to N10-009, expect conceptual, definition-style questions rather than deep hands-on scenarios."}, {"type": "compare", "heading": "SDN vs. SD-WAN", "columns": ["SDN", "SD-WAN"], "rows": [{"label": "Scope", "values": ["Any network", "Wide area links between sites"]}, {"label": "Core idea", "values": ["Split control plane from data plane", "Pick the best WAN path in real time"]}, {"label": "Example", "values": ["Central controller programs data center switches", "Branch traffic moves from MPLS to broadband when latency spikes"]}]}, {"type": "key_term", "term": "Infrastructure as Code (IaC)", "definition": "Network and server configuration defined in version-controlled files instead of one-off manual changes. Consistent, repeatable and auditable.", "example": "A new branch''s switch and firewall configuration is generated from the same template as the last forty branches."}, {"type": "compare", "heading": "Perimeter vs. zero trust", "columns": ["Perimeter model", "Zero trust"], "rows": [{"label": "Inside the network is", "values": ["Trusted", "Not trusted by default"]}, {"label": "Each request", "values": ["Checked at the edge only", "Checked every time against identity, device and context"]}, {"label": "Motto", "values": ["Castle and moat", "Never trust, always verify"]}]}, {"type": "scenario", "prompt": "A company wants each branch to use MPLS normally but fail over to broadband or LTE automatically based on live performance. What fits?", "choices": [{"id": "a", "text": "SDN"}, {"id": "b", "text": "SD-WAN"}, {"id": "c", "text": "IaC"}, {"id": "d", "text": "Zero trust"}], "answer": "b", "why": "Choosing among WAN links dynamically is SD-WAN."}, {"type": "scenario", "prompt": "An employee on the office LAN must still pass identity and device checks to reach an internal app. Which model is this?", "choices": [{"id": "a", "text": "Perimeter security"}, {"id": "b", "text": "Zero trust"}, {"id": "c", "text": "Collapsed core"}, {"id": "d", "text": "Community cloud"}], "answer": "b", "why": "Being inside the network earns no automatic trust."}, {"type": "callout", "variant": "tip", "text": "SD-WAN is specifically about WAN links; SDN is the broader control and data plane split. Zero trust means location earns nothing."}]'::jsonb where id = '92b302c0-7557-41f3-836f-917e344cb9bb';

-- Domain 1 Recap
update lessons set content_blocks = '[{"text": "Domain 1 Recap: Networking Concepts", "type": "title", "overview": "A condensed pass over every lesson in this domain, the OSI model, appliances, cloud, ports/protocols, media, topologies, IPv4 addressing and subnetting, and modern network trends.", "examContext": "This recap has no questions of its own; the Domain Checkpoint right after it draws fresh scenario questions from everything covered across all 10 lessons."}, {"type": "term_set", "heading": "OSI, devices and cloud", "terms": [{"term": "OSI layers", "short": "7 application, 6 presentation, 5 session, 4 transport, 3 network, 2 data link, 1 physical."}, {"term": "PDUs", "short": "Segment or datagram, packet, frame, bits."}, {"term": "Hub / switch / router", "short": "Layer 1 / layer 2 by MAC / layer 3 by IP."}, {"term": "Forward / reverse proxy", "short": "Acts for clients going out / servers being reached."}, {"term": "IaaS / PaaS / SaaS", "short": "You manage the OS up / just code / just use the app."}]}, {"type": "term_set", "heading": "Protocols and media", "terms": [{"term": "Key ports", "short": "SSH 22, DNS 53, DHCP 67 and 68, HTTP 80, NTP 123, SNMP 161 and 162, LDAP 389, HTTPS 443, RDP 3389."}, {"term": "DORA", "short": "Discover, offer, request, acknowledge."}, {"term": "Fiber", "short": "Single-mode for kilometers; multimode inside buildings."}, {"term": "Cat 6a", "short": "10 Gbps at the full 100 m."}, {"term": "Spine-leaf", "short": "Every leaf to every spine, nothing else."}]}, {"type": "term_set", "heading": "Addressing and modern networks", "terms": [{"term": "Private ranges", "short": "10/8, 172.16/12, 192.168/16."}, {"term": "APIPA", "short": "169.254 means DHCP failed."}, {"term": "Usable hosts", "short": "2 to the host bits, minus 2. Block size is 256 minus the mask octet."}, {"term": "SDN / SD-WAN", "short": "Control plane split / smart WAN path selection."}, {"term": "Zero trust", "short": "Never trust, always verify."}]}, {"type": "scenario", "prompt": "How many usable hosts are in a /27?", "choices": [{"id": "a", "text": "32"}, {"id": "b", "text": "30"}, {"id": "c", "text": "62"}, {"id": "d", "text": "14"}], "answer": "b", "why": "5 host bits: 32 addresses minus 2."}, {"type": "scenario", "prompt": "Which DNS record maps a name to an IPv6 address?", "choices": [{"id": "a", "text": "A"}, {"id": "b", "text": "AAAA"}, {"id": "c", "text": "PTR"}, {"id": "d", "text": "CNAME"}], "answer": "b", "why": "AAAA is the IPv6 address record."}, {"type": "scenario", "prompt": "Which fiber suits a 20 km campus link?", "choices": [{"id": "a", "text": "Multimode"}, {"id": "b", "text": "Single-mode"}, {"id": "c", "text": "Cat 8"}, {"id": "d", "text": "Coax"}], "answer": "b", "why": "Long distance means single-mode."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = 'b903ed18-cea7-4a4c-9eb3-49fbcc70030c';

-- Routing Technologies
update lessons set content_blocks = '[{"text": "Routing Technologies", "type": "title", "overview": "How routers decide where to send traffic: static routes, the major dynamic routing protocol families, route selection, and network address translation.", "examContext": "Expect scenario questions asking you to pick a routing protocol or predict which route a router will choose based on administrative distance or metric."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Routing table", "short": "A router''s list of destination networks and how to reach them."}, {"term": "Static route", "short": "Entered by hand; predictable but doesn''t adapt to failures."}, {"term": "Default route", "short": "0.0.0.0/0, the route of last resort, usually toward the internet."}, {"term": "Administrative distance", "short": "Picks between different sources of a route. Lower wins."}, {"term": "Metric", "short": "Picks between routes from the same protocol."}]}, {"type": "compare", "heading": "Dynamic routing protocol families", "columns": ["Protocols", "How it works", "Used for"], "rows": [{"label": "Distance vector", "values": ["RIP, EIGRP", "Shares its table with neighbors; hop count or composite metric", "Smaller or simpler internal networks"]}, {"label": "Link state", "values": ["OSPF", "Every router maps the topology and calculates shortest paths", "Larger internal networks; fast convergence"]}, {"label": "Path vector", "values": ["BGP", "Chooses by AS path and policy", "Between autonomous systems; the internet"]}]}, {"type": "diagram", "heading": "Administrative distance (lower is preferred)", "diagram": {"kind": "ladder", "rungs": [{"label": "Directly connected: 0"}, {"label": "Static: 1"}, {"label": "EIGRP: 90"}, {"label": "OSPF: 110"}, {"label": "RIP: 120"}], "top": "most trusted", "bottom": "least"}}, {"type": "key_term", "term": "NAT and PAT", "definition": "NAT lets private addresses share public ones. PAT, the most common form, maps every internal host to one public IP with different source ports.", "example": "Two hundred office PCs browse the web through a single public address; the router tracks each by port number."}, {"type": "scenario", "prompt": "A router has a static route and an OSPF route to the same network. Which does it use by default?", "choices": [{"id": "a", "text": "The OSPF route, because OSPF is dynamic"}, {"id": "b", "text": "The static route, because its administrative distance is lower"}, {"id": "c", "text": "Both, load balanced"}, {"id": "d", "text": "Whichever has the lower metric"}], "answer": "b", "why": "Different sources are compared by administrative distance: static 1 beats OSPF 110.", "trap": "Metric only compares routes within the same protocol."}, {"type": "scenario", "prompt": "Which protocol exchanges routes between internet service providers?", "choices": [{"id": "a", "text": "OSPF"}, {"id": "b", "text": "RIP"}, {"id": "c", "text": "BGP"}, {"id": "d", "text": "EIGRP"}], "answer": "c", "why": "BGP is the path vector protocol between autonomous systems."}, {"type": "callout", "variant": "tip", "text": "Different sources: administrative distance. Same protocol: metric. BGP runs between autonomous systems."}]'::jsonb where id = 'b6ac3f57-475f-49cb-b2d8-930c48e02b49';

-- Switching Fundamentals and VLANs
update lessons set content_blocks = '[{"text": "Switching Fundamentals and VLANs", "type": "title", "overview": "How a switch learns MAC addresses and forwards frames, and how VLANs split one physical switch into multiple logical broadcast domains.", "examContext": "VLAN scenarios (which ports belong to which VLAN, why two hosts on different VLANs can''t talk without a router) are a recurring exam theme."}, {"type": "diagram", "heading": "How a switch handles a frame", "diagram": {"kind": "flow", "steps": [{"label": "Learn", "note": "Record the source MAC against the incoming port."}, {"label": "Look up", "note": "Find the destination MAC in the table."}, {"label": "Forward or flood", "note": "Known: send out one port. Unknown: flood every port in the VLAN."}]}}, {"type": "key_term", "term": "VLAN", "definition": "A logical group of switch ports forming its own broadcast domain. Devices in different VLANs need a router or layer 3 switch to talk.", "example": "Phones on VLAN 20 and PCs on VLAN 10 share a switch but can''t reach each other until a layer 3 switch routes between them."}, {"type": "key_term", "term": "Broadcast domain", "definition": "Every device that receives a broadcast from any one of them. A VLAN sets that boundary.", "example": "Splitting one large VLAN of 800 devices into four smaller ones cuts the broadcast traffic each device sees."}, {"type": "term_set", "heading": "Port configuration", "terms": [{"term": "Access port", "short": "Belongs to one VLAN; connects an end device."}, {"term": "Speed and duplex", "short": "Should autonegotiate; a mismatch causes collisions and slowness."}, {"term": "Port security", "short": "Limits which MAC addresses can use a port."}, {"term": "Interface errors", "short": "CRC errors, collisions, runts and giants point to physical or duplex problems."}]}, {"type": "compare", "heading": "Power over Ethernet", "columns": ["Standard", "Typical devices"], "rows": [{"label": "PoE", "values": ["802.3af", "IP phones, basic APs"]}, {"label": "PoE+", "values": ["802.3at", "Cameras, dual-band APs"]}, {"label": "PoE++ (4PPoE)", "values": ["802.3bt", "PTZ cameras, high-end APs, small displays"]}]}, {"type": "scenario", "prompt": "Two PCs are plugged into the same switch but can''t ping each other. One is on VLAN 10 and the other on VLAN 30. What''s needed?", "choices": [{"id": "a", "text": "A crossover cable"}, {"id": "b", "text": "Routing between the VLANs"}, {"id": "c", "text": "Port security"}, {"id": "d", "text": "PoE"}], "answer": "b", "why": "Different VLANs are different broadcast domains; traffic between them must be routed."}, {"type": "scenario", "prompt": "A port shows many late collisions and the link is slow. What''s the most likely cause?", "choices": [{"id": "a", "text": "VLAN mismatch"}, {"id": "b", "text": "Duplex mismatch"}, {"id": "c", "text": "Wrong DNS server"}, {"id": "d", "text": "STP blocking"}], "answer": "b", "why": "Collisions on a switched link point to a duplex mismatch."}, {"type": "callout", "variant": "tip", "text": "Different VLAN means different broadcast domain, which means it must be routed. Collisions on a switch port suggest duplex."}]'::jsonb where id = '04ad67f0-64ab-4756-bd44-a751cdc951fe';

-- Spanning Tree, Trunking, and Link Aggregation
update lessons set content_blocks = '[{"text": "Spanning Tree, Trunking, and Link Aggregation", "type": "title", "overview": "How switched networks avoid catastrophic loops, how one link carries traffic for many VLANs, and how multiple physical links act as one logical link.", "examContext": "Expect direct questions on what STP prevents and what a native VLAN is, plus scenario questions describing a broadcast storm."}, {"type": "paragraph", "text": "Redundant links between switches add fault tolerance, but redundant layer 2 paths create **loops**. Ethernet frames have no TTL, so a loop circulates traffic forever until the network collapses."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Broadcast storm", "short": "Flooded traffic multiplying around a loop until the network is unusable."}, {"term": "Spanning Tree Protocol (STP)", "short": "Blocks redundant paths to prevent loops, keeping a backup ready."}, {"term": "Trunk port (802.1Q)", "short": "Carries many VLANs over one link, tagging each frame."}, {"term": "Native VLAN", "short": "The one VLAN whose frames cross the trunk untagged."}, {"term": "LACP", "short": "Bundles several physical links into one logical link."}]}, {"type": "key_term", "term": "Spanning Tree Protocol", "definition": "Logically blocks redundant paths while keeping them ready to activate if the active path fails.", "example": "Two uplinks connect an access switch to the core. STP blocks one; when the other is cut, the blocked one starts forwarding."}, {"type": "compare", "heading": "Access port vs. trunk port", "columns": ["Access", "Trunk"], "rows": [{"label": "VLANs carried", "values": ["One", "Many"]}, {"label": "Tagging", "values": ["Untagged", "802.1Q tags, except the native VLAN"]}, {"label": "Connects", "values": ["End devices", "Switches, routers, some servers"]}]}, {"type": "key_term", "term": "Link aggregation (LACP)", "definition": "Combines physical links into one logical link for more bandwidth and redundancy. Negotiated with 802.3ad / 802.1AX.", "example": "Four 10 Gbps links between two core switches act as one 40 Gbps link and keep working if one cable fails."}, {"type": "scenario", "prompt": "Right after a technician adds a second cable between two switches, the whole network slows to a crawl. What''s the most likely cause?", "choices": [{"id": "a", "text": "A routing loop"}, {"id": "b", "text": "A layer 2 loop because STP is disabled or misconfigured"}, {"id": "c", "text": "A DHCP failure"}, {"id": "d", "text": "A native VLAN mismatch"}], "answer": "b", "why": "A new redundant layer 2 path without STP creates a broadcast storm.", "trap": "It''s not a routing loop: routed packets have a TTL and die out."}, {"type": "scenario", "prompt": "VLAN 1 traffic arrives on the wrong VLAN at the far end of a trunk, while all tagged VLANs work. What should be checked?", "choices": [{"id": "a", "text": "LACP settings"}, {"id": "b", "text": "Native VLAN on both ends"}, {"id": "c", "text": "PoE budget"}, {"id": "d", "text": "Port security"}], "answer": "b", "why": "Untagged traffic lands in each side''s native VLAN; a mismatch misplaces it."}, {"type": "callout", "variant": "tip", "text": "Network collapses after adding a redundant cable? Think layer 2 loop and STP. Untagged trouble on a trunk? Check the native VLAN."}]'::jsonb where id = 'a9b92195-f33a-4656-9b83-6c49903fbe59';

-- Wireless Standards and Security
update lessons set content_blocks = '[{"text": "Wireless Standards and Security", "type": "title", "overview": "The generations of 802.11 Wi-Fi standards, the frequency bands they use, and the encryption/authentication standards that secure wireless traffic.", "examContext": "Expect direct recall questions on standard-to-frequency mapping and on which WPA version is currently recommended."}, {"type": "compare", "heading": "802.11 standards", "columns": ["Bands", "Key feature"], "rows": [{"label": "802.11a", "values": ["5 GHz", "Early, obsolete"]}, {"label": "802.11b / g", "values": ["2.4 GHz", "Longer range, more interference"]}, {"label": "802.11n (Wi-Fi 4)", "values": ["2.4 and 5 GHz", "Introduced MIMO"]}, {"label": "802.11ac (Wi-Fi 5)", "values": ["5 GHz only", "Wider channels, MU-MIMO"]}, {"label": "802.11ax (Wi-Fi 6 / 6E)", "values": ["2.4, 5 and 6 GHz (6E)", "OFDMA for dense environments"]}]}, {"type": "compare", "heading": "2.4 GHz vs. 5 GHz", "columns": ["2.4 GHz", "5 GHz"], "rows": [{"label": "Range and wall penetration", "values": ["Better", "Worse"]}, {"label": "Non-overlapping channels", "values": ["Only 3 (1, 6, 11)", "Many"]}, {"label": "Interference", "values": ["Microwaves, Bluetooth, cordless phones", "Much less"]}, {"label": "Throughput", "values": ["Lower", "Higher"]}]}, {"type": "diagram", "heading": "Wireless security over time", "diagram": {"kind": "ladder", "rungs": [{"label": "WPA3", "note": "Current. SAE handshake resists offline dictionary attacks."}, {"label": "WPA2", "note": "AES-CCMP; the long-time standard, but its handshake is attackable."}, {"label": "WPA", "note": "A stopgap after WEP."}, {"label": "WEP", "note": "Broken. Never use.", "muted": true}], "top": "strongest", "bottom": "weakest"}}, {"type": "key_term", "term": "SAE", "definition": "Simultaneous Authentication of Equals, WPA3''s handshake. A captured handshake can''t be cracked offline, even with a fairly weak password.", "example": "An attacker records the handshake at a café hoping to crack it at home; with WPA3, that recording is useless."}, {"type": "scenario", "prompt": "Which standard only operates in the 5 GHz band?", "choices": [{"id": "a", "text": "802.11n"}, {"id": "b", "text": "802.11ac"}, {"id": "c", "text": "802.11g"}, {"id": "d", "text": "802.11ax"}], "answer": "b", "why": "Wi-Fi 5 (802.11ac) is 5 GHz only."}, {"type": "scenario", "prompt": "A warehouse full of metal shelving needs the longest reach through obstacles. Which band fits better?", "choices": [{"id": "a", "text": "2.4 GHz"}, {"id": "b", "text": "5 GHz"}, {"id": "c", "text": "6 GHz"}, {"id": "d", "text": "Any band; it doesn''t matter"}], "answer": "a", "why": "2.4 GHz penetrates obstacles and reaches further."}, {"type": "callout", "variant": "tip", "text": "2.4 GHz: range, three channels, interference. 5 GHz: speed, many channels. WPA3 with SAE is the current answer."}]'::jsonb where id = '71a9ce22-66de-4103-adbb-488759f4b00a';

-- Wireless Deployment and Site Considerations
update lessons set content_blocks = '[{"text": "Wireless Deployment and Site Considerations", "type": "title", "overview": "How to plan and deploy a wireless network that actually performs well in the real environment it''s installed in.", "examContext": "Expect scenario questions about coverage gaps, channel overlap, and choosing between AP deployment models."}, {"type": "key_term", "term": "Site survey and heat map", "definition": "Walk the space with survey tools before and after installing, and produce a heat map of signal strength over the floor plan.", "example": "The heat map shows a red dead zone in the corner conference room, so an AP is added there before move-in."}, {"type": "compare", "heading": "AP deployment models", "columns": ["Autonomous", "Controller based", "Cloud managed"], "rows": [{"label": "Managed", "values": ["One AP at a time", "Centrally by a wireless LAN controller", "Through a cloud dashboard"]}, {"label": "Roaming", "values": ["Limited", "Seamless across many APs", "Seamless across many APs"]}, {"label": "Fits", "values": ["Very small sites", "Larger on-premises deployments", "Distributed sites, small IT teams"]}]}, {"type": "term_set", "heading": "Placement and antennas", "terms": [{"term": "Channel overlap", "short": "Neighboring APs on overlapping channels interfere; plan non-overlapping channels."}, {"term": "Omnidirectional antenna", "short": "Radiates in all directions; general office coverage."}, {"term": "Directional antenna", "short": "Focuses signal one way; point-to-point links."}, {"term": "Cellular (LTE, 5G)", "short": "Wide-area wireless for WAN failover or IoT where cable isn''t practical."}]}, {"type": "scenario", "prompt": "Users at the far end of a building keep dropping Wi-Fi, though APs elsewhere show strong signal. What should be done?", "choices": [{"id": "a", "text": "Switch to WPA3"}, {"id": "b", "text": "Run a site survey and add or move an AP"}, {"id": "c", "text": "Change the VLAN"}, {"id": "d", "text": "Disable 5 GHz"}], "answer": "b", "why": "It''s a coverage gap; a fresh survey guides AP placement."}, {"type": "scenario", "prompt": "Two neighboring APs are both set to 2.4 GHz channel 6 and users see poor performance. What''s the fix?", "choices": [{"id": "a", "text": "Use channels 1 and 11 for neighbors"}, {"id": "b", "text": "Use channel 7 on one"}, {"id": "c", "text": "Increase both to full power"}, {"id": "d", "text": "Use omnidirectional antennas"}], "answer": "a", "why": "Assign non-overlapping channels to adjacent APs.", "trap": "Channel 7 overlaps channel 6. On 2.4 GHz only 1, 6 and 11 don''t overlap."}, {"type": "callout", "variant": "tip", "text": "Coverage gaps are fixed with surveys and AP placement, not encryption or VLAN changes."}]'::jsonb where id = '5a4064bc-2cea-40b2-bba6-f918a5956620';

-- Physical Installation Factors
update lessons set content_blocks = '[{"text": "Physical Installation Factors", "type": "title", "overview": "The physical-world details that keep a data center or wiring closet running reliably: rack layout, cabling discipline, environment, and power.", "examContext": "Expect direct recall questions naming a specific piece of equipment (UPS, PDU) or documentation type (rack diagram, IDF/MDF)."}, {"type": "compare", "heading": "MDF vs. IDF", "columns": ["MDF", "IDF"], "rows": [{"label": "Role", "values": ["Main point where all cabling converges", "Secondary closet serving a floor or area"]}, {"label": "Usually holds", "values": ["Core switching and the demarcation point", "Access switches"]}, {"label": "Connects to", "values": ["Every IDF", "The MDF"]}]}, {"type": "term_set", "heading": "Rack and cabling practices", "terms": [{"term": "Rack diagram", "short": "Shows what occupies each rack unit (U)."}, {"term": "Cable management", "short": "Patch panels, trays and labels keep cables traceable and secure."}]}, {"type": "compare", "heading": "UPS vs. PDU", "columns": ["UPS", "PDU"], "rows": [{"label": "Does", "values": ["Battery backup through outages", "Distributes power to rack equipment"]}, {"label": "Buys you", "values": ["Time for a graceful shutdown", "Outlets, monitoring, per-outlet control"]}]}, {"type": "term_set", "heading": "Environment", "terms": [{"term": "Too hot", "short": "Equipment failures."}, {"term": "Too humid", "short": "Condensation and corrosion."}, {"term": "Too dry", "short": "Static discharge."}, {"term": "Fire suppression", "short": "Gas based, not water, which would destroy the equipment."}]}, {"type": "scenario", "prompt": "Switches in a closet fail intermittently, mostly on hot afternoons since an air conditioner broke. What''s the root cause?", "choices": [{"id": "a", "text": "Duplex mismatch"}, {"id": "b", "text": "Inadequate cooling"}, {"id": "c", "text": "Bad VLAN design"}, {"id": "d", "text": "Wrong PoE standard"}], "answer": "b", "why": "Failures that track heat point to environmental control."}, {"type": "scenario", "prompt": "Which device keeps a server rack running for a few minutes when building power drops?", "choices": [{"id": "a", "text": "PDU"}, {"id": "b", "text": "UPS"}, {"id": "c", "text": "Patch panel"}, {"id": "d", "text": "IDF"}], "answer": "b", "why": "A UPS provides battery backup."}, {"type": "callout", "variant": "tip", "text": "UPS keeps it running; PDU spreads the power. Failures that track the weather point to cooling."}]'::jsonb where id = '491dd58a-275c-4304-bd18-07f655a08e2e';

-- Domain 2 Recap
update lessons set content_blocks = '[{"text": "Domain 2 Recap: Network Implementation", "type": "title", "overview": "A condensed pass over every lesson in this domain, routing, switching/VLANs, STP/trunking/LACP, wireless standards, wireless deployment, and physical installation.", "examContext": "This recap has no questions of its own; the Domain Checkpoint right after it draws fresh scenario questions from everything covered across all 6 lessons."}, {"type": "term_set", "heading": "Routing and switching", "terms": [{"term": "Administrative distance", "short": "Connected 0, static 1, OSPF 110: picks between sources."}, {"term": "Metric", "short": "Picks within one protocol."}, {"term": "RIP, EIGRP / OSPF / BGP", "short": "Distance vector / link state / path vector between autonomous systems."}, {"term": "PAT", "short": "Many hosts share one public IP by port."}, {"term": "VLANs", "short": "Separate broadcast domains; cross-VLAN traffic must be routed."}]}, {"type": "term_set", "heading": "Loops and links", "terms": [{"term": "STP", "short": "Blocks redundant paths; prevents broadcast storms."}, {"term": "Trunk / native VLAN", "short": "Tagged VLANs on one link / the untagged one."}, {"term": "LACP", "short": "Bundles links for bandwidth and redundancy."}, {"term": "PoE, PoE+, PoE++", "short": "802.3af, at, bt: more power each step."}]}, {"type": "term_set", "heading": "Wireless and physical", "terms": [{"term": "2.4 / 5 GHz", "short": "Range and 3 channels / speed and many channels."}, {"term": "Wi-Fi 6E", "short": "Adds 6 GHz; OFDMA for density."}, {"term": "WPA3 / SAE", "short": "Current; resists offline cracking."}, {"term": "MDF / IDF", "short": "Main convergence / floor closet."}, {"term": "UPS / PDU", "short": "Battery backup / power distribution."}]}, {"type": "scenario", "prompt": "Which stops broadcast storms on redundant switch links?", "choices": [{"id": "a", "text": "LACP"}, {"id": "b", "text": "STP"}, {"id": "c", "text": "PAT"}, {"id": "d", "text": "PoE"}], "answer": "b", "why": "STP blocks loops."}, {"type": "scenario", "prompt": "Which band has only three non-overlapping channels?", "choices": [{"id": "a", "text": "2.4 GHz"}, {"id": "b", "text": "5 GHz"}, {"id": "c", "text": "6 GHz"}, {"id": "d", "text": "All of them"}], "answer": "a", "why": "Channels 1, 6 and 11."}, {"type": "scenario", "prompt": "Which routing protocol is link state?", "choices": [{"id": "a", "text": "RIP"}, {"id": "b", "text": "OSPF"}, {"id": "c", "text": "BGP"}, {"id": "d", "text": "EIGRP"}], "answer": "b", "why": "OSPF builds a full topology map."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = '63042c20-aafa-4a9b-8cf1-d668905f21fa';

-- Organizational Processes and Documentation
update lessons set content_blocks = '[{"text": "Organizational Processes and Documentation", "type": "title", "overview": "The agreements, procedures, and documentation that keep network operations consistent, auditable, and recoverable.", "examContext": "Expect definition-matching questions naming a specific document or agreement type."}, {"type": "paragraph", "text": "Well-run networks are documented, not held in someone''s head. Good documentation turns a 3 a.m. outage into a known, repeatable recovery."}, {"type": "compare", "heading": "Agreements", "columns": ["Purpose"], "rows": [{"label": "SLA", "values": ["Minimum service levels from a provider: uptime, response time"]}, {"label": "MOU", "values": ["Non-binding statement of intent to work together"]}, {"label": "NDA", "values": ["Legal protection for shared confidential information"]}]}, {"type": "compare", "heading": "Physical vs. logical diagram", "columns": ["Physical diagram", "Logical diagram"], "rows": [{"label": "Shows", "values": ["Hardware, cabling, physical connections", "IP addressing, VLANs, traffic flow"]}, {"label": "Answers", "values": ["Which cable goes to which port?", "Which subnet is this server in, and how does traffic route?"]}], "cue": ["\"Wires and boxes\"", "\"Addresses and flows\""]}, {"type": "term_set", "heading": "Other records", "terms": [{"term": "Standard operating procedure (SOP)", "short": "Repeatable steps for a routine task, whoever performs it."}, {"term": "Wiring diagram", "short": "Exact cable runs and terminations, port by port."}, {"term": "Asset inventory", "short": "Every piece of hardware and software owned."}, {"term": "IPAM", "short": "Tracks which addresses and subnets are allocated to what."}, {"term": "Life-cycle management", "short": "From acquisition to end of life (EOL) and end of support (EOS)."}]}, {"type": "scenario", "prompt": "A technician needs to know which VLAN and subnet a server belongs to and how traffic reaches it from the branch office. Which document helps most?", "choices": [{"id": "a", "text": "Physical network diagram"}, {"id": "b", "text": "Logical network diagram"}, {"id": "c", "text": "Wiring diagram"}, {"id": "d", "text": "Rack diagram"}], "answer": "b", "why": "VLANs, addressing and traffic flow are on the logical diagram."}, {"type": "scenario", "prompt": "Two new servers keep receiving the same static IP from different admins. Which practice would prevent this?", "choices": [{"id": "a", "text": "SLA"}, {"id": "b", "text": "IPAM"}, {"id": "c", "text": "NDA"}, {"id": "d", "text": "Rack diagram"}], "answer": "b", "why": "IP address management tracks allocations and prevents conflicts."}, {"type": "callout", "variant": "tip", "text": "Physical is wires and boxes; logical is addresses and flow. Know SLA, MOU and NDA cold."}]'::jsonb where id = '69856dee-0686-4a7c-aa5e-5d913ae5b763';

-- Network Monitoring Technologies
update lessons set content_blocks = '[{"text": "Network Monitoring Technologies", "type": "title", "overview": "How network devices report their status and how administrators collect, centralize, and act on that data.", "examContext": "Expect direct recall on SNMP components/versions and on what specific monitoring tool or metric addresses a given scenario."}, {"type": "compare", "heading": "SNMP polling vs. traps", "columns": ["Polling (GET)", "Trap"], "rows": [{"label": "Direction", "values": ["Manager asks the agent", "Agent tells the manager"]}, {"label": "Style", "values": ["Pull, on a schedule", "Push, when an event happens"]}, {"label": "Best for", "values": ["Routine trend collection", "Immediate notification"]}], "intro": "SNMP v1 and v2c use community strings; **SNMPv3** adds authentication and encryption."}, {"type": "term_set", "heading": "Collecting the data", "terms": [{"term": "Syslog", "short": "Devices send log messages to a central syslog server."}, {"term": "NetFlow / sFlow / IPFIX", "short": "Summaries of who talked to whom and how much, without payloads."}, {"term": "Packet capture", "short": "Full packet contents for deep analysis; far more data."}, {"term": "Port mirroring (SPAN)", "short": "Copies a port''s traffic to a monitoring tool outside the traffic path."}]}, {"type": "key_term", "term": "Baseline", "definition": "What normal looks like for a metric. Without one, an alert threshold is a guess.", "example": "Core switch CPU normally sits at 20 to 30%. An alert at 70% is meaningful only because the baseline is known."}, {"type": "term_set", "heading": "Common health metrics", "terms": [{"term": "Interface errors and utilization", "short": "Physical problems and capacity."}, {"term": "CPU and memory", "short": "Device load."}, {"term": "Environmental sensors", "short": "Temperature and humidity."}, {"term": "Uptime", "short": "Availability and unexpected reboots."}]}, {"type": "scenario", "prompt": "A team wants instant notification the moment a switch''s power supply fails. Which SNMP mechanism fits?", "choices": [{"id": "a", "text": "Polling"}, {"id": "b", "text": "A trap"}, {"id": "c", "text": "A community string"}, {"id": "d", "text": "NetFlow"}], "answer": "b", "why": "Traps push event notifications immediately."}, {"type": "scenario", "prompt": "An IDS needs to see a copy of traffic on a switch without being inline. What should be configured?", "choices": [{"id": "a", "text": "Syslog"}, {"id": "b", "text": "Port mirroring (SPAN)"}, {"id": "c", "text": "SNMP polling"}, {"id": "d", "text": "NTP"}], "answer": "b", "why": "SPAN copies traffic to the monitoring port."}, {"type": "callout", "variant": "tip", "text": "Polling pulls on a schedule; traps push when something happens. NetFlow summarizes, packet capture records everything."}]'::jsonb where id = '874b400a-9212-483b-9620-32a2b52457cb';

-- Disaster Recovery Concepts
update lessons set content_blocks = '[{"text": "Disaster Recovery Concepts", "type": "title", "overview": "The metrics and strategies organizations use to plan for, survive, and recover from major outages or disasters.", "examContext": "RPO vs. RTO is one of the most frequently tested single distinctions on the entire exam."}, {"type": "diagram", "heading": "RPO and RTO", "diagram": {"kind": "timeline", "event": "Disaster", "before": {"label": "RPO", "note": "Maximum acceptable data loss, measured back in time. Drives backup frequency."}, "after": [{"label": "RTO", "note": "Maximum acceptable downtime. Drives recovery site and failover design."}]}, "caption": "RPO looks backward; RTO looks forward. Mixing them up is the most common mistake on this topic."}, {"type": "compare", "heading": "Reliability metrics", "columns": ["MTBF", "MTTR"], "rows": [{"label": "Measures", "values": ["Average time between failures", "Average time to repair"]}, {"label": "Better when", "values": ["Higher", "Lower"]}]}, {"type": "compare", "heading": "Backup types", "columns": ["Full", "Incremental", "Differential"], "rows": [{"label": "Copies", "values": ["Everything", "Changes since the last backup of any kind", "Changes since the last full"]}, {"label": "Backup speed", "values": ["Slowest", "Fastest", "Medium, growing daily"]}, {"label": "Restore needs", "values": ["Just the full", "The full plus every incremental", "The full plus the latest differential"]}]}, {"type": "compare", "heading": "Recovery sites", "columns": ["Hot", "Warm", "Cold"], "rows": [{"label": "Ready", "values": ["Fully equipped, near instant", "Partly equipped; some setup", "Space, power and cooling only"]}, {"label": "Cost", "values": ["Highest", "Medium", "Lowest"]}]}, {"type": "scenario", "prompt": "A business says it can lose no more than 15 minutes of transaction data. Which metric is this?", "choices": [{"id": "a", "text": "RTO"}, {"id": "b", "text": "RPO"}, {"id": "c", "text": "MTTR"}, {"id": "d", "text": "MTBF"}], "answer": "b", "why": "Acceptable data loss is RPO.", "trap": "15 minutes sounds like a time to recover, but the question is about data lost, which is RPO."}, {"type": "scenario", "prompt": "Backups run full on Sunday and differential every other night. The server fails Thursday. What''s needed to restore?", "choices": [{"id": "a", "text": "Sunday''s full only"}, {"id": "b", "text": "Sunday''s full and Wednesday''s differential"}, {"id": "c", "text": "Sunday''s full and every differential"}, {"id": "d", "text": "Wednesday''s differential only"}], "answer": "b", "why": "Each differential holds everything since the last full, so only the latest one is needed."}, {"type": "callout", "variant": "tip", "text": "Data loss is RPO; downtime is RTO. Incremental restores need every piece; differential needs only the last one."}]'::jsonb where id = '6acfa0ae-5228-4176-b84f-e5a095afced4';

-- Implementing IPv4 and IPv6 Network Services
update lessons set content_blocks = '[{"text": "Implementing IPv4 and IPv6 Network Services", "type": "title", "overview": "The core services that make IP networks usable day to day: automatic addressing (DHCP), name resolution (DNS), time sync (NTP), and IPv6 fundamentals.", "examContext": "Expect DHCP process ordering questions (DORA), DNS record-type matching, and IPv6 address-type identification."}, {"type": "diagram", "heading": "DHCP: DORA", "diagram": {"kind": "flow", "steps": [{"label": "Discover", "note": "Client broadcasts for a server."}, {"label": "Offer", "note": "Server proposes a configuration."}, {"label": "Request", "note": "Client broadcasts its choice, so other servers know."}, {"label": "Acknowledge", "note": "Server finalizes the lease."}]}}, {"type": "term_set", "heading": "DHCP features", "terms": [{"term": "Reservation", "short": "A fixed address handed to one MAC address every time."}, {"term": "Relay / IP helper", "short": "Forwards DHCP broadcasts across routers to a remote server."}]}, {"type": "compare", "heading": "DNS record types", "columns": ["Maps"], "rows": [{"label": "A", "values": ["Name to IPv4"]}, {"label": "AAAA", "values": ["Name to IPv6"]}, {"label": "CNAME", "values": ["Name to another name (alias)"]}, {"label": "MX", "values": ["Domain to its mail servers"]}, {"label": "TXT", "values": ["Free text: verification, SPF, DKIM"]}, {"label": "PTR", "values": ["IP back to a name"]}, {"label": "NS", "values": ["Domain to its authoritative servers"]}], "intro": "**NTP** keeps clocks in sync for logs, certificates and Kerberos."}, {"type": "compare", "heading": "IPv6 address types", "columns": ["Prefix", "IPv4 equivalent"], "rows": [{"label": "Global unicast", "values": ["2000::/3", "Public address"]}, {"label": "Unique local", "values": ["fc00::/7", "Private address"]}, {"label": "Link-local", "values": ["fe80::/10", "APIPA-like; never routed"]}, {"label": "Multicast", "values": ["ff00::/8", "Replaces broadcast entirely"]}]}, {"type": "scenario", "prompt": "A network printer must always get the same address, but the team wants it managed through DHCP. What should be configured?", "choices": [{"id": "a", "text": "A DHCP relay"}, {"id": "b", "text": "A DHCP reservation"}, {"id": "c", "text": "A PTR record"}, {"id": "d", "text": "A static route"}], "answer": "b", "why": "A reservation ties an address to the printer''s MAC."}, {"type": "scenario", "prompt": "An interface shows only an address starting with fe80. What does that tell you?", "choices": [{"id": "a", "text": "It has a public IPv6 address"}, {"id": "b", "text": "It has only a link-local address and can talk on the local segment only"}, {"id": "c", "text": "It''s using IPv4 APIPA"}, {"id": "d", "text": "It''s a multicast address"}], "answer": "b", "why": "fe80 is link-local, created automatically and never routed."}, {"type": "callout", "variant": "tip", "text": "DORA in order. IPv6 has no broadcast at all; fe80 is link-local and stays on the segment."}]'::jsonb where id = 'e4738f97-69dc-4fad-ab09-9b002ff8e035';

-- Network Access and Management Methods
update lessons set content_blocks = '[{"text": "Network Access and Management Methods", "type": "title", "overview": "How administrators remotely and securely access, configure, and automate network devices.", "examContext": "Expect scenario questions distinguishing in-band from out-of-band management and identifying the right remote access protocol."}, {"type": "compare", "heading": "In-band vs. out-of-band management", "columns": ["In-band", "Out-of-band"], "rows": [{"label": "Path", "values": ["Same network as production traffic", "Separate dedicated path: console server, management port"]}, {"label": "If production fails", "values": ["Unreachable too", "Still reachable"]}, {"label": "Cost", "values": ["Cheap and convenient", "Extra hardware and links"]}], "cue": ["\"Over the normal network\"", "\"Router is unreachable\""]}, {"type": "compare", "heading": "VPN types", "columns": ["Site-to-site", "Client-to-site"], "rows": [{"label": "Connects", "values": ["Two whole networks", "One remote user''s device"]}, {"label": "Runs", "values": ["Permanently between gateways", "When the user connects"]}, {"label": "Example", "values": ["Branch office to headquarters", "Employee on hotel Wi-Fi"]}]}, {"type": "term_set", "heading": "Remote access protocols", "terms": [{"term": "SSH", "short": "Encrypted command line; replaces Telnet."}, {"term": "RDP", "short": "Full graphical Windows desktop."}, {"term": "API (RESTful)", "short": "Scripts push configuration or pull status from many devices at once; central to IaC."}]}, {"type": "scenario", "prompt": "A bad configuration change knocks a remote router off the network. How can an admin still reach it?", "choices": [{"id": "a", "text": "SSH over the production network"}, {"id": "b", "text": "Through out-of-band management such as a console server"}, {"id": "c", "text": "RDP"}, {"id": "d", "text": "A client-to-site VPN"}], "answer": "b", "why": "Only an independent path survives when the production path is down.", "trap": "SSH and VPN both ride the same broken network."}, {"type": "scenario", "prompt": "Which provides encrypted command-line access to a switch?", "choices": [{"id": "a", "text": "Telnet"}, {"id": "b", "text": "SSH"}, {"id": "c", "text": "RDP"}, {"id": "d", "text": "HTTP"}], "answer": "b", "why": "SSH is the encrypted replacement for Telnet."}, {"type": "callout", "variant": "tip", "text": "Device unreachable over the network? Out-of-band. Two offices permanently linked? Site-to-site VPN."}]'::jsonb where id = 'cd8e19ce-d9c8-45fc-9ac7-4569cabd949d';

-- Domain 3 Recap
update lessons set content_blocks = '[{"text": "Domain 3 Recap: Network Operations", "type": "title", "overview": "A condensed pass over every lesson in this domain, documentation/agreements, monitoring, disaster recovery, IPv4/IPv6 services, and access/management methods.", "examContext": "This recap has no questions of its own; the Domain Checkpoint right after it draws fresh scenario questions from everything covered across all 5 lessons."}, {"type": "term_set", "heading": "Documentation and monitoring", "terms": [{"term": "SLA / MOU / NDA", "short": "Service levels / non-binding intent / confidentiality."}, {"term": "Physical / logical diagram", "short": "Wires and hardware / addressing and flow."}, {"term": "SNMP poll / trap", "short": "Pull on schedule / push on event. v3 adds encryption."}, {"term": "Syslog, NetFlow, packet capture", "short": "Central logs, flow summaries, full payloads."}, {"term": "Baseline", "short": "What normal looks like."}]}, {"type": "term_set", "heading": "Disaster recovery", "terms": [{"term": "RPO / RTO", "short": "Maximum data loss / maximum downtime."}, {"term": "MTBF / MTTR", "short": "Between failures, higher is better / to repair, lower is better."}, {"term": "Full / incremental / differential", "short": "Everything / since last backup / since last full."}, {"term": "Hot / warm / cold", "short": "Ready now / some setup / empty room."}]}, {"type": "term_set", "heading": "Services and access", "terms": [{"term": "DORA, reservation, relay", "short": "Lease steps / fixed address per MAC / crosses routers."}, {"term": "IPv6", "short": "No broadcast; fe80 link-local; fc00 unique local."}, {"term": "In-band / out-of-band", "short": "Shares production / survives production outages."}, {"term": "Site-to-site / client-to-site VPN", "short": "Network to network / one user in."}]}, {"type": "scenario", "prompt": "Which metric drives how often backups must run?", "choices": [{"id": "a", "text": "RTO"}, {"id": "b", "text": "RPO"}, {"id": "c", "text": "MTBF"}, {"id": "d", "text": "MTTR"}], "answer": "b", "why": "RPO caps data loss."}, {"type": "scenario", "prompt": "Which SNMP message is sent by the device without being asked?", "choices": [{"id": "a", "text": "GET"}, {"id": "b", "text": "Trap"}, {"id": "c", "text": "SET"}, {"id": "d", "text": "Walk"}], "answer": "b", "why": "Traps are unsolicited."}, {"type": "scenario", "prompt": "What replaces broadcast in IPv6?", "choices": [{"id": "a", "text": "Anycast"}, {"id": "b", "text": "Multicast"}, {"id": "c", "text": "Unicast"}, {"id": "d", "text": "Link-local"}], "answer": "b", "why": "IPv6 uses multicast for every former broadcast role."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = 'd5bedaf9-add9-453b-8c0f-a3d43d13dc5e';

-- Basic Network Security Concepts
update lessons set content_blocks = '[{"text": "Basic Network Security Concepts", "type": "title", "overview": "The foundational security concepts every network defense strategy is built on.", "examContext": "These concepts underpin nearly every other question in this domain, so expect them woven into scenario questions, not just tested standalone."}, {"type": "diagram", "heading": "What network security protects", "diagram": {"kind": "triad", "points": [{"label": "Confidentiality", "note": "Only the right people see the data."}, {"label": "Integrity", "note": "Data isn''t altered in transit or storage."}, {"label": "Availability", "note": "The network is there when it''s needed."}], "center": "CIA"}}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Defense in depth", "short": "Layered, independent controls so one failure isn''t fatal."}, {"term": "Least privilege", "short": "Only the minimum access needed."}, {"term": "Segmentation", "short": "Isolated zones so a breach in one doesn''t expose the rest."}, {"term": "Attack surface", "short": "Every point an attacker could try; fewer ports and services means smaller."}]}, {"type": "key_term", "term": "Defense in depth", "definition": "Multiple independent layers, so no single control is a point of total failure.", "example": "An attacker phishes a password, but MFA blocks the login; even if that failed, segmentation keeps finance servers out of reach."}, {"type": "term_set", "heading": "Common vulnerabilities", "terms": [{"term": "Unpatched software or firmware", "short": "Known flaws left open after a fix exists."}, {"term": "Default credentials", "short": "Factory usernames and passwords never changed."}, {"term": "Unnecessary ports and services", "short": "Extra attack surface."}, {"term": "Misconfigurations", "short": "Overly permissive rules, weak encryption, open management interfaces."}, {"term": "Zero-day", "short": "A flaw unknown to the vendor, with no patch when exploited."}]}, {"type": "scenario", "prompt": "An attacker got past a single perimeter firewall and then had free access to every internal system. What principle was missing?", "choices": [{"id": "a", "text": "Least privilege"}, {"id": "b", "text": "Defense in depth"}, {"id": "c", "text": "Availability"}, {"id": "d", "text": "Zero-day patching"}], "answer": "b", "why": "A single control failing led to total compromise: there was no second, independent layer."}, {"type": "scenario", "prompt": "New security cameras are installed with their factory admin passwords unchanged. Which vulnerability is this?", "choices": [{"id": "a", "text": "Zero-day"}, {"id": "b", "text": "Default credentials"}, {"id": "c", "text": "Misconfigured ACL"}, {"id": "d", "text": "Unpatched firmware"}], "answer": "b", "why": "Factory credentials left in place."}, {"type": "callout", "variant": "tip", "text": "One failure leading to total compromise means a layer is missing. The fix is adding another independent control."}]'::jsonb where id = 'e57e0fca-7fac-415e-bb33-38516943c69f';

-- Common Network Attacks I: Denial of Service and On-Path Attacks
update lessons set content_blocks = '[{"text": "Common Network Attacks I: Denial of Service and On-Path Attacks", "type": "title", "overview": "Attacks aimed at disrupting availability, and attacks that insert an attacker between two communicating parties.", "examContext": "Expect scenario questions describing symptoms (a flood of traffic, unexpected MAC/IP mappings) and asking you to name the attack."}, {"type": "compare", "heading": "DoS vs. DDoS", "columns": ["DoS", "DDoS"], "rows": [{"label": "Sources", "values": ["One", "Many, often a botnet"]}, {"label": "Block by source IP?", "values": ["Usually possible", "Not practical"]}]}, {"type": "key_term", "term": "On-path attack", "definition": "Formerly man-in-the-middle. The attacker sits between two parties and can read or change their traffic unnoticed.", "example": "On a café network, an attacker relays a victim''s traffic through a laptop and captures every unencrypted login."}, {"type": "compare", "heading": "Three ways to get on the path", "columns": ["What the attacker forges", "Layer"], "rows": [{"label": "ARP spoofing", "values": ["MAC to IP mapping, often for the gateway", "Layer 2, local LAN"]}, {"label": "DNS spoofing", "values": ["Hostname to IP mapping", "Application layer"]}, {"label": "MAC flooding", "values": ["Thousands of fake MACs fill the switch table so it floods all traffic", "Layer 2, switch"]}]}, {"type": "key_term", "term": "ARP spoofing", "definition": "Forged ARP replies tie the attacker''s MAC to another host''s IP, so traffic flows through the attacker.", "example": "Running arp -a on several PCs shows the default gateway''s IP mapped to the same unfamiliar MAC address."}, {"type": "scenario", "prompt": "A web server is overwhelmed by traffic from tens of thousands of home routers and cameras worldwide. What''s happening?", "choices": [{"id": "a", "text": "DoS"}, {"id": "b", "text": "DDoS"}, {"id": "c", "text": "ARP spoofing"}, {"id": "d", "text": "MAC flooding"}], "answer": "b", "why": "Many distributed sources, typically a botnet: DDoS."}, {"type": "scenario", "prompt": "Users typing the bank''s correct web address are landing on a fake site with a different IP. Which attack fits best?", "choices": [{"id": "a", "text": "ARP spoofing"}, {"id": "b", "text": "DNS spoofing"}, {"id": "c", "text": "MAC flooding"}, {"id": "d", "text": "DDoS"}], "answer": "b", "why": "The name resolves to the wrong IP: DNS spoofing."}, {"type": "callout", "variant": "tip", "text": "ARP spoofing lies about MAC addresses on the LAN; DNS spoofing lies about names. Both set up on-path attacks."}]'::jsonb where id = '4da7098d-9b84-4fcb-bd2b-2458a54f0303';

-- Common Network Attacks II: VLAN Hopping, Rogue Devices, and Social Engineering
update lessons set content_blocks = '[{"text": "Common Network Attacks II: VLAN Hopping, Rogue Devices, and Social Engineering", "type": "title", "overview": "Attacks that exploit switch/VLAN configuration, rogue infrastructure planted on a network, and attacks that target people rather than technology.", "examContext": "Expect the exam to describe a specific scenario (a fake AP, an unexpected DHCP server) and ask you to name the exact attack."}, {"type": "key_term", "term": "VLAN hopping", "definition": "Getting traffic into a VLAN it shouldn''t reach, by double tagging 802.1Q frames or tricking a port into trunk mode.", "example": "An attacker on an access port negotiates a trunk with the switch and suddenly sees traffic from every VLAN."}, {"type": "key_term", "term": "Rogue DHCP server", "definition": "An unauthorized DHCP server handing out bad settings, often a malicious gateway or DNS server.", "example": "Someone plugs in a home router; half the floor gets 192.168.0.x addresses and loses access to company resources."}, {"type": "compare", "heading": "Rogue AP vs. evil twin", "columns": ["Rogue AP", "Evil twin"], "rows": [{"label": "Definition", "values": ["Any unauthorized AP on the network", "A rogue AP mimicking a legitimate SSID"]}, {"label": "Intent", "values": ["Malicious or innocent", "Malicious"]}, {"label": "Example", "values": ["An employee''s personal router under a desk", "\"Corp-WiFi\" broadcast from an attacker''s laptop in the lobby"]}], "intro": "Every evil twin is a rogue AP; not every rogue AP is an evil twin."}, {"type": "term_set", "heading": "Social engineering", "terms": [{"term": "Phishing", "short": "Fraudulent messages to steal credentials or install malware."}, {"term": "Tailgating", "short": "Following someone through a secure door."}, {"term": "Shoulder surfing", "short": "Watching someone enter credentials."}, {"term": "Pretexting", "short": "A made-up scenario or identity to manipulate someone."}]}, {"type": "scenario", "prompt": "Clients suddenly receive an unfamiliar default gateway and DNS server from DHCP. What should you suspect?", "choices": [{"id": "a", "text": "Evil twin"}, {"id": "b", "text": "Rogue DHCP server"}, {"id": "c", "text": "MAC flooding"}, {"id": "d", "text": "VLAN hopping"}], "answer": "b", "why": "Bad configuration from DHCP points to a rogue DHCP server."}, {"type": "scenario", "prompt": "A caller claims to be from the IT vendor and asks the receptionist for the Wi-Fi password to fix an urgent outage. What technique is this?", "choices": [{"id": "a", "text": "Tailgating"}, {"id": "b", "text": "Pretexting"}, {"id": "c", "text": "Shoulder surfing"}, {"id": "d", "text": "Evil twin"}], "answer": "b", "why": "A fabricated scenario to gain information."}, {"type": "callout", "variant": "tip", "text": "Evil twin copies a real SSID; rogue AP is any unauthorized AP. Unexpected gateway from DHCP means a rogue DHCP server."}]'::jsonb where id = 'c64b2918-bb2c-4cad-a777-2a8a7b20f4e3';

-- Network Hardening and Access Control
update lessons set content_blocks = '[{"text": "Network Hardening and Access Control", "type": "title", "overview": "Concrete steps to reduce a device''s attack surface, and the technologies that control who and what can connect to a network at all.", "examContext": "Expect direct recall on 802.1X''s role and on distinguishing RADIUS from TACACS+."}, {"type": "term_set", "heading": "Device hardening", "terms": [{"term": "Disable unused ports and services", "short": "Shrinks the attack surface."}, {"term": "Change default credentials", "short": "Before the device goes live."}, {"term": "Least privilege for admins", "short": "Only the access each admin needs."}, {"term": "Patch firmware and software", "short": "Close known flaws."}]}, {"type": "key_term", "term": "802.1X", "definition": "Port-based access control: a device must authenticate, usually against RADIUS, before passing traffic. Works on wired and wireless.", "example": "A visitor plugs a laptop into a conference room jack and gets nothing until it authenticates."}, {"type": "compare", "heading": "RADIUS vs. TACACS+", "columns": ["RADIUS", "TACACS+"], "rows": [{"label": "Transport", "values": ["UDP", "TCP"]}, {"label": "Encryption", "values": ["Password only", "Entire packet"]}, {"label": "AAA", "values": ["Combines authentication and authorization", "Separates all three"]}, {"label": "Typical use", "values": ["Network access: Wi-Fi, VPN, 802.1X", "Admins logging into routers and switches"]}], "cue": ["\"Users getting on the network\"", "\"Admins managing devices\""]}, {"type": "compare", "heading": "ACL vs. NAC", "columns": ["ACL", "NAC"], "rows": [{"label": "Decides on", "values": ["IPs, ports, protocols", "Device posture: patches, antivirus"]}, {"label": "Result", "values": ["Permit or deny traffic", "Admit, restrict or quarantine the device"]}]}, {"type": "scenario", "prompt": "A company wants admins'' router logins fully encrypted with command-level authorization. Which should it use?", "choices": [{"id": "a", "text": "RADIUS"}, {"id": "b", "text": "TACACS+"}, {"id": "c", "text": "802.1X"}, {"id": "d", "text": "LDAP"}], "answer": "b", "why": "TACACS+ encrypts everything and authorizes per command."}, {"type": "scenario", "prompt": "A laptop missing security patches connects and is placed in a quarantine VLAN until it updates. What did this?", "choices": [{"id": "a", "text": "ACL"}, {"id": "b", "text": "NAC"}, {"id": "c", "text": "SNMP"}, {"id": "d", "text": "STP"}], "answer": "b", "why": "NAC evaluates posture and quarantines non-compliant devices."}, {"type": "callout", "variant": "tip", "text": "Users getting on the network: RADIUS. Admins managing devices: TACACS+. Posture checks: NAC."}]'::jsonb where id = '7629923f-1b15-443b-9edf-3426b4526b15';

-- Segmentation and Security Appliances
update lessons set content_blocks = '[{"text": "Segmentation and Security Appliances", "type": "title", "overview": "The dedicated hardware and network zones organizations deploy to inspect, filter, and contain traffic.", "examContext": "Expect direct recall on firewall generations and the IDS-vs-IPS distinction, plus a scenario on DMZ placement."}, {"type": "diagram", "heading": "Firewall generations", "diagram": {"kind": "ladder", "rungs": [{"label": "WAF", "note": "HTTP specific; protects web applications."}, {"label": "NGFW", "note": "Stateful plus application awareness and IPS."}, {"label": "Stateful", "note": "Tracks connections; allows return traffic. The modern baseline."}, {"label": "Packet filtering", "note": "Per packet by IP, port and protocol; no state."}], "top": "most specialized", "bottom": "most basic"}}, {"type": "compare", "heading": "IDS vs. IPS", "columns": ["IDS", "IPS"], "rows": [{"label": "Position", "values": ["Out of path, often on a SPAN port", "Inline"]}, {"label": "Action", "values": ["Alerts", "Blocks in real time"]}, {"label": "Control type", "values": ["Detective", "Preventive"]}], "cue": ["\"Alerts an analyst\"", "\"Drops packets\""]}, {"type": "diagram", "heading": "A screened subnet (DMZ)", "diagram": {"kind": "flow", "steps": [{"label": "Internet"}, {"label": "Outer firewall", "note": "Lets the public reach DMZ services only."}, {"label": "DMZ", "note": "Web and mail servers."}, {"label": "Inner firewall", "note": "Tightly limits DMZ to internal traffic."}, {"label": "Internal network"}]}, "caption": "A compromised DMZ server doesn''t directly expose internal systems."}, {"type": "scenario", "prompt": "A device sits inline and drops packets matching an exploit signature. What is it?", "choices": [{"id": "a", "text": "IDS"}, {"id": "b", "text": "IPS"}, {"id": "c", "text": "Packet sniffer"}, {"id": "d", "text": "Proxy"}], "answer": "b", "why": "Inline and blocking means IPS."}, {"type": "scenario", "prompt": "Where should a company place its public web server?", "choices": [{"id": "a", "text": "On the internal LAN"}, {"id": "b", "text": "In the DMZ"}, {"id": "c", "text": "On the management VLAN"}, {"id": "d", "text": "Outside all firewalls"}], "answer": "b", "why": "Public services belong in the screened subnet, isolated from the internal network."}, {"type": "callout", "variant": "tip", "text": "IDS detects, IPS prevents. Public-facing servers go in the DMZ."}]'::jsonb where id = '1c6fc27a-5f23-4474-a8f1-4d11045dba5c';

-- Domain 4 Recap
update lessons set content_blocks = '[{"text": "Domain 4 Recap: Network Security", "type": "title", "overview": "A condensed pass over every lesson in this domain, basic concepts, DoS/on-path attacks, VLAN hopping/rogue devices/social engineering, hardening/access control, and segmentation/appliances.", "examContext": "This recap has no questions of its own; the Domain Checkpoint right after it draws fresh scenario questions from everything covered across all 5 lessons."}, {"type": "term_set", "heading": "Concepts and attacks", "terms": [{"term": "Defense in depth / least privilege / segmentation", "short": "Layers / minimum access / isolated zones."}, {"term": "DoS / DDoS", "short": "One source / many, hard to filter."}, {"term": "ARP / DNS spoofing", "short": "Lies about MACs on the LAN / lies about names."}, {"term": "MAC flooding", "short": "Overflows the switch table so it floods."}, {"term": "VLAN hopping", "short": "Double tagging or a rogue trunk."}, {"term": "Rogue AP / evil twin", "short": "Any unauthorized AP / one copying a real SSID."}]}, {"type": "term_set", "heading": "Controls and appliances", "terms": [{"term": "802.1X", "short": "Authenticate before the port passes traffic."}, {"term": "RADIUS / TACACS+", "short": "Network access, UDP / device admin, TCP, full encryption."}, {"term": "ACL / NAC", "short": "Traffic rules / device posture."}, {"term": "Stateful firewall / NGFW / WAF", "short": "Tracks connections / app aware / web apps."}, {"term": "IDS / IPS", "short": "Alerts / blocks."}, {"term": "DMZ", "short": "Public servers between two firewalls."}]}, {"type": "scenario", "prompt": "Which attack fills a switch''s MAC table so it floods all traffic?", "choices": [{"id": "a", "text": "ARP spoofing"}, {"id": "b", "text": "MAC flooding"}, {"id": "c", "text": "VLAN hopping"}, {"id": "d", "text": "DDoS"}], "answer": "b", "why": "Overflowing the table makes the switch fail open."}, {"type": "scenario", "prompt": "Which AAA protocol encrypts the whole packet?", "choices": [{"id": "a", "text": "RADIUS"}, {"id": "b", "text": "TACACS+"}, {"id": "c", "text": "LDAP"}, {"id": "d", "text": "SNMPv2c"}], "answer": "b", "why": "TACACS+ encrypts everything."}, {"type": "scenario", "prompt": "A fake access point broadcasts the company''s SSID in the parking lot. What is it?", "choices": [{"id": "a", "text": "Evil twin"}, {"id": "b", "text": "Rogue DHCP"}, {"id": "c", "text": "Bluejacking"}, {"id": "d", "text": "War driving"}], "answer": "a", "why": "A rogue AP copying a real SSID."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = '7ce72855-8306-4d8c-bdf3-4cc7766aaeab';

-- Troubleshooting Methodology
update lessons set content_blocks = '[{"text": "Troubleshooting Methodology", "type": "title", "overview": "A structured, repeatable process for diagnosing and resolving network problems, rather than guessing at fixes.", "examContext": "Expect ordering questions and scenario questions that describe a step being skipped and ask you to identify which one."}, {"type": "diagram", "heading": "The seven-step troubleshooting methodology", "diagram": {"kind": "flow", "steps": [{"label": "Identify the problem", "note": "Gather information, question users, find what changed, duplicate it."}, {"label": "Establish a theory", "note": "Question the obvious first."}, {"label": "Test the theory", "note": "Confirmed: plan next steps. Not confirmed: new theory or escalate."}, {"label": "Plan of action", "note": "Decide the fix and its possible effects."}, {"label": "Implement or escalate", "note": "Make the change, or hand it up."}, {"label": "Verify functionality", "note": "Confirm it works; add preventive measures."}, {"label": "Document", "note": "Findings, actions and outcomes."}]}}, {"type": "key_term", "term": "Duplicate the problem", "definition": "Reproduce the issue yourself, when possible, to confirm it''s real and see it firsthand.", "example": "A user says the VPN drops every hour; the technician connects from a test laptop and watches it drop at 60 minutes."}, {"type": "key_term", "term": "Escalation", "definition": "Passing the issue to someone with more access, expertise or authority when your theory isn''t confirmed or the fix is beyond your scope.", "example": "The theory points to the ISP''s circuit, which the technician can''t touch, so a ticket goes to the carrier."}, {"type": "scenario", "prompt": "A technician replaces a user''s switch port module as soon as the user reports slowness. What did the technician skip?", "choices": [{"id": "a", "text": "Documenting findings"}, {"id": "b", "text": "Identifying the problem and testing a theory"}, {"id": "c", "text": "Verifying functionality"}, {"id": "d", "text": "Escalation"}], "answer": "b", "why": "Jumping straight to a fix skips the first three steps."}, {"type": "scenario", "prompt": "After fixing a misconfigured VLAN, what should the technician do before documenting?", "choices": [{"id": "a", "text": "Establish a new theory"}, {"id": "b", "text": "Verify full system functionality"}, {"id": "c", "text": "Duplicate the problem"}, {"id": "d", "text": "Escalate"}], "answer": "b", "why": "Verify it works, and add preventive measures, then document."}, {"type": "callout", "variant": "tip", "text": "Most \"what step was skipped\" questions are about jumping ahead to the fix. Document is always last."}]'::jsonb where id = '4946eea7-023a-4d9c-a8fe-4fa994b52565';

-- Cabling and Physical Interface Issues
update lessons set content_blocks = '[{"text": "Cabling and Physical Interface Issues", "type": "title", "overview": "The physical-layer problems most often responsible for ''mystery'' connectivity and performance issues.", "examContext": "Expect the exam to describe a specific symptom (intermittent link, distance-related dropouts) and ask you to name the underlying cabling problem."}, {"type": "paragraph", "text": "Many problems that look complicated are simple physical layer issues: a bad cable, the wrong connector, or a run that''s too long."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Attenuation", "short": "Signal weakens with distance; past the rated length, errors follow."}, {"term": "Crosstalk", "short": "One pair''s signal bleeds into the next."}, {"term": "dB loss", "short": "How much signal a run loses; more than expected points to cabling or connectors."}]}, {"type": "compare", "heading": "Match the symptom to the cause", "columns": ["Likely cause"], "rows": [{"label": "Link never comes up, especially fiber", "values": ["TX and RX reversed"]}, {"label": "Link up, but many collisions and slowness", "values": ["Duplex mismatch"]}, {"label": "Intermittent errors that worsen with distance or load", "values": ["Attenuation or crosstalk"]}, {"label": "Fiber errors after a tidy-up of the cable tray", "values": ["Bend radius violation"]}, {"label": "Intermittent or no link after re-termination", "values": ["Bad connector or termination"]}, {"label": "Errors on a run longer than 100 m of copper", "values": ["Distance limit exceeded"]}]}, {"type": "scenario", "prompt": "A newly installed fiber link between two switches shows no link light on either end. Both transceivers match. What''s the likely cause?", "choices": [{"id": "a", "text": "Crosstalk"}, {"id": "b", "text": "TX and RX reversed"}, {"id": "c", "text": "Duplex mismatch"}, {"id": "d", "text": "Attenuation"}], "answer": "b", "why": "A fiber link that never comes up often has its transmit and receive swapped."}, {"type": "scenario", "prompt": "A 140 m copper run to a warehouse office has constant errors. What''s the problem?", "choices": [{"id": "a", "text": "Duplex mismatch"}, {"id": "b", "text": "Exceeded distance, causing attenuation"}, {"id": "c", "text": "Wrong VLAN"}, {"id": "d", "text": "TX and RX reversed"}], "answer": "b", "why": "Copper Ethernet is rated to 100 m."}, {"type": "callout", "variant": "tip", "text": "Never comes up: TX/RX. Up but slow with collisions: duplex. Worse over distance: attenuation."}]'::jsonb where id = '8ac95301-3728-4231-ab37-e7d8c9bc7de2';

-- Network Service Issues
update lessons set content_blocks = '[{"text": "Network Service Issues", "type": "title", "overview": "Diagnosing failures in the core services (DHCP, DNS, addressing) that networks depend on to function at all.", "examContext": "Expect scenario questions describing symptoms like APIPA addresses or intermittent name resolution failures and asking for the root cause."}, {"type": "term_set", "heading": "Addressing problems", "terms": [{"term": "DHCP scope exhaustion", "short": "No addresses left to lease; new devices fail as the network grows."}, {"term": "APIPA (169.254)", "short": "The client couldn''t reach DHCP and assigned itself an address."}, {"term": "IP address conflict", "short": "Two devices share an address; intermittent trouble for both."}]}, {"type": "term_set", "heading": "DNS problems", "terms": [{"term": "Wrong DNS server", "short": "Network works, names don''t resolve."}, {"term": "Bad DNS record", "short": "A wrong or missing record points somewhere wrong."}, {"term": "Stale cache", "short": "Old answer after a legitimate change, until it expires or is flushed."}]}, {"type": "diagram", "heading": "Diagnosing \"I can''t reach the server\"", "diagram": {"kind": "flow", "steps": [{"label": "Check the address", "note": "169.254? DHCP problem."}, {"label": "Ping by IP", "note": "Fails? Connectivity or routing."}, {"label": "Ping by name", "note": "IP works but name fails? DNS."}]}}, {"type": "scenario", "prompt": "Users can reach an intranet server at 10.1.5.20 but not at intranet.corp.local. What''s the problem?", "choices": [{"id": "a", "text": "Routing"}, {"id": "b", "text": "DNS"}, {"id": "c", "text": "DHCP scope"}, {"id": "d", "text": "Cabling"}], "answer": "b", "why": "The path works by IP, so name resolution is failing."}, {"type": "scenario", "prompt": "New laptops in a growing office get 169.254 addresses, while existing devices work. What''s most likely?", "choices": [{"id": "a", "text": "IP conflict"}, {"id": "b", "text": "DHCP scope exhaustion"}, {"id": "c", "text": "Wrong DNS server"}, {"id": "d", "text": "Stale DNS cache"}], "answer": "b", "why": "Existing leases work but new clients can''t get one: the pool is empty."}, {"type": "callout", "variant": "tip", "text": "Works by IP but not by name: DNS. 169.254: go look at DHCP, not the cable."}]'::jsonb where id = '5d7d3a57-f0b4-4cf2-9c8f-93e980a6767a';

-- Performance Issues: Congestion and Latency
update lessons set content_blocks = '[{"text": "Performance Issues: Congestion and Latency", "type": "title", "overview": "The vocabulary and causes behind ''the network feels slow'' complaints, and why different symptoms point to different root causes.", "examContext": "Latency vs. jitter vs. packet loss vs. bandwidth is a frequently tested set of distinct definitions."}, {"type": "compare", "heading": "What \"slow\" really means", "columns": ["Definition", "Felt as"], "rows": [{"label": "Bandwidth", "values": ["Theoretical maximum rate of a link", "The advertised speed"]}, {"label": "Throughput", "values": ["Actual rate achieved", "Real transfer speed, often lower"]}, {"label": "Latency", "values": ["Time for a packet to arrive", "Delay, lag on calls"]}, {"label": "Jitter", "values": ["Variation in latency", "Choppy voice and video"]}, {"label": "Packet loss", "values": ["Packets that never arrive", "Retransmissions, gaps, dropped calls"]}]}, {"type": "key_term", "term": "Congestion", "definition": "More traffic offered than a link or device can handle. Buffers fill, and latency, jitter and loss all rise.", "example": "Every evening backup jobs saturate the WAN link and the branch''s VoIP calls start breaking up."}, {"type": "key_term", "term": "QoS", "definition": "Quality of service prioritizes latency-sensitive traffic such as voice over bulk transfers.", "example": "Voice packets are tagged and sent first, so calls stay clear even while backups run."}, {"type": "scenario", "prompt": "VoIP calls are choppy and garbled even though speed tests show plenty of bandwidth. What''s the likely issue and fix?", "choices": [{"id": "a", "text": "Low bandwidth; buy a faster link"}, {"id": "b", "text": "Jitter; apply QoS for voice"}, {"id": "c", "text": "DNS failure; change servers"}, {"id": "d", "text": "Attenuation; replace cables"}], "answer": "b", "why": "Choppy real-time audio with adequate bandwidth points to jitter, fixed by prioritizing voice.", "trap": "More bandwidth is the tempting answer, but the problem is inconsistent timing, not capacity."}, {"type": "scenario", "prompt": "A 1 Gbps link only transfers files at 600 Mbps. Which term describes the 600 Mbps?", "choices": [{"id": "a", "text": "Bandwidth"}, {"id": "b", "text": "Throughput"}, {"id": "c", "text": "Latency"}, {"id": "d", "text": "Jitter"}], "answer": "b", "why": "Throughput is the actual achieved rate."}, {"type": "callout", "variant": "tip", "text": "Choppy voice despite fast speeds means jitter and QoS, not more bandwidth."}]'::jsonb where id = 'a86c871d-a6cd-4366-8116-c1e27fdcc9a2';

-- Performance Issues: Wireless and Interference
update lessons set content_blocks = '[{"text": "Performance Issues: Wireless and Interference", "type": "title", "overview": "Wireless networks fail and slow down for reasons that don''t apply to wired links, understanding those unique causes is essential for troubleshooting Wi-Fi complaints.", "examContext": "Expect a scenario naming a specific interference source or symptom (e.g. signal drops near a microwave) and asking you to identify the cause."}, {"type": "term_set", "heading": "Sources of wireless trouble", "terms": [{"term": "Microwaves, cordless phones, Bluetooth", "short": "Crowd the 2.4 GHz band."}, {"term": "Neighboring Wi-Fi", "short": "Especially on overlapping channels in dense buildings."}, {"term": "Obstructions", "short": "Concrete and metal absorb or reflect signal; worse at 5 and 6 GHz."}, {"term": "Co-channel interference", "short": "Several APs on the same channel competing for airtime."}]}, {"type": "compare", "heading": "RSSI vs. SNR", "columns": ["RSSI", "SNR"], "rows": [{"label": "Measures", "values": ["Signal strength at the receiver", "Signal compared to background noise"]}, {"label": "Bad looks like", "values": ["Very negative dBm, for example -85 dBm", "Noise close to the signal level"]}, {"label": "Can look fine while performance is bad?", "values": ["Yes", "Less often"]}]}, {"type": "compare", "heading": "Coverage vs. capacity", "columns": ["Coverage problem", "Capacity problem"], "rows": [{"label": "Symptom", "values": ["Weak signal at the edges", "Strong signal, poor performance"]}, {"label": "Cause", "values": ["Too far from an AP or blocked", "Too many clients on one AP or channel"]}, {"label": "Fix", "values": ["Move or add APs for reach", "Add more APs to share the load"]}]}, {"type": "scenario", "prompt": "A conference room with 80 laptops has excellent signal strength but terrible Wi-Fi performance. What''s the issue?", "choices": [{"id": "a", "text": "Coverage gap"}, {"id": "b", "text": "Client and channel saturation"}, {"id": "c", "text": "Attenuation"}, {"id": "d", "text": "Wrong encryption"}], "answer": "b", "why": "It''s a capacity problem: more APs are needed, not a stronger one."}, {"type": "scenario", "prompt": "Wi-Fi in a break room drops whenever someone heats lunch. What''s the cause?", "choices": [{"id": "a", "text": "Co-channel interference"}, {"id": "b", "text": "Microwave interference on 2.4 GHz"}, {"id": "c", "text": "DHCP exhaustion"}, {"id": "d", "text": "Bend radius"}], "answer": "b", "why": "Microwave ovens operate near 2.4 GHz."}, {"type": "callout", "variant": "tip", "text": "Good signal doesn''t guarantee good performance. Strong signal plus a crowd means capacity."}]'::jsonb where id = 'ee19b5d9-a650-4860-8cb9-a639bd9afbcd';

-- Command-Line Troubleshooting Tools
update lessons set content_blocks = '[{"text": "Command-Line Troubleshooting Tools", "type": "title", "overview": "The core command-line utilities every network technician reaches for first, and exactly what each one tells you.", "examContext": "Expect direct ''which tool would you use to...'' questions, this is one of the most heavily tested, high-yield lessons on the entire exam."}, {"type": "compare", "heading": "Which tool answers which question", "columns": ["Answers"], "rows": [{"label": "ping", "values": ["Is it reachable, and how long does a round trip take?"]}, {"label": "traceroute / tracert", "values": ["Where along the path does it fail or slow down?"]}, {"label": "pathping", "values": ["Loss and latency statistics at every hop over time (Windows)."]}, {"label": "ipconfig / ifconfig / ip", "values": ["What''s my address, mask, gateway and DNS?"]}, {"label": "nslookup / dig", "values": ["What does the DNS server say for this name?"]}, {"label": "arp", "values": ["Which MAC is mapped to this IP?"]}, {"label": "netstat", "values": ["What connections and listening ports are on this host?"]}, {"label": "tcpdump / Wireshark", "values": ["What exactly is on the wire?"]}, {"label": "nmap", "values": ["Which hosts are live and which ports are open?"]}], "intro": "This is one of the highest-yield lessons on the exam."}, {"type": "key_term", "term": "traceroute", "definition": "Lists each hop to a destination with latency at each one, so you can see where a problem starts.", "example": "Latency is 10 ms for the first four hops and jumps to 300 ms at hop five, the ISP''s edge router."}, {"type": "scenario", "prompt": "A user can reach some websites but one is very slow. Which tool shows where along the path the delay begins?", "choices": [{"id": "a", "text": "ping"}, {"id": "b", "text": "traceroute"}, {"id": "c", "text": "nslookup"}, {"id": "d", "text": "netstat"}], "answer": "b", "why": "Traceroute shows per-hop latency."}, {"type": "scenario", "prompt": "An admin suspects a server has an unexpected service listening for connections. Which tool, run on the server, shows this?", "choices": [{"id": "a", "text": "arp"}, {"id": "b", "text": "netstat"}, {"id": "c", "text": "dig"}, {"id": "d", "text": "tracert"}], "answer": "b", "why": "netstat lists local connections and listening ports.", "trap": "nmap could find it from outside, but on the host itself netstat is the direct answer."}, {"type": "callout", "variant": "tip", "text": "Reachable: ping. Where it breaks: traceroute. Names: nslookup or dig. Local ports: netstat."}]'::jsonb where id = '2331729e-c44c-4f7d-99fc-c20bf2a1d605';

-- Additional Troubleshooting Tools and Software
update lessons set content_blocks = '[{"text": "Additional Troubleshooting Tools and Software", "type": "title", "overview": "Purpose-built hardware and software tools that go beyond basic command-line utilities for physical-layer and wireless diagnostics.", "examContext": "Expect direct matching questions: a described tool or its output, and you name it."}, {"type": "compare", "heading": "Cable and physical layer tools", "columns": ["What it does"], "rows": [{"label": "Cable tester", "values": ["Checks continuity and pinout"]}, {"label": "Cable certifier", "values": ["Proves a cable meets a category standard, such as Cat 6a"]}, {"label": "Tone generator and probe", "values": ["Traces an unlabeled cable to its other end"]}, {"label": "TDR", "values": ["Finds the distance to a fault on copper"]}, {"label": "OTDR", "values": ["Finds breaks, splices and loss on fiber"]}, {"label": "Light meter", "values": ["Measures optical power on a fiber link"]}]}, {"type": "compare", "heading": "Tester vs. certifier vs. TDR", "columns": ["Cable tester", "Cable certifier", "TDR / OTDR"], "rows": [{"label": "Answers", "values": ["Is it wired right?", "Does it meet the standard?", "How far away is the break?"]}], "cue": ["\"Pinout\"", "\"Meets Cat 6a\"", "\"Distance to fault\""]}, {"type": "term_set", "heading": "Software and wireless tools", "terms": [{"term": "Protocol analyzer", "short": "Captures and decodes traffic, such as Wireshark."}, {"term": "Wi-Fi analyzer", "short": "Surveys channels, signal and interference; makes heat maps."}, {"term": "Speed tester", "short": "Measures real throughput against what the ISP promised."}]}, {"type": "scenario", "prompt": "A 250 m fiber run has failed and the technician needs to know exactly where the break is. Which tool?", "choices": [{"id": "a", "text": "Cable tester"}, {"id": "b", "text": "TDR"}, {"id": "c", "text": "OTDR"}, {"id": "d", "text": "Tone generator"}], "answer": "c", "why": "OTDR locates faults on fiber.", "trap": "TDR works the same way but on copper."}, {"type": "scenario", "prompt": "A patch panel has dozens of unlabeled cables and you need to find the one going to office 214. Which tool?", "choices": [{"id": "a", "text": "Light meter"}, {"id": "b", "text": "Tone generator and probe"}, {"id": "c", "text": "Cable certifier"}, {"id": "d", "text": "Wi-Fi analyzer"}], "answer": "b", "why": "Put a tone on the cable at one end and find it at the other."}, {"type": "callout", "variant": "tip", "text": "TDR is copper, OTDR is fiber. A tester checks wiring; a certifier proves the category."}]'::jsonb where id = 'd4adb8fc-02d5-440b-ad76-d8dbc2759ef4';

-- Domain 5 Recap
update lessons set content_blocks = '[{"text": "Domain 5 Recap: Network Troubleshooting", "type": "title", "overview": "A condensed pass over every lesson in this domain, methodology, cabling issues, network service issues, congestion/latency, wireless interference, and the command-line/hardware tools used to diagnose them.", "examContext": "This recap has no questions of its own; the Domain Checkpoint right after it draws fresh scenario questions from everything covered across all 7 lessons."}, {"type": "term_set", "heading": "Method and physical", "terms": [{"term": "Seven steps", "short": "Identify, theory, test, plan, implement, verify, document."}, {"term": "Attenuation / crosstalk", "short": "Weakens over distance / bleeds between pairs."}, {"term": "TX/RX reversed", "short": "Fiber link never comes up."}, {"term": "Duplex mismatch", "short": "Link up, collisions, slow."}]}, {"type": "term_set", "heading": "Services and performance", "terms": [{"term": "169.254", "short": "DHCP failed."}, {"term": "IP works, name doesn''t", "short": "DNS."}, {"term": "Bandwidth / throughput", "short": "Theoretical / actual."}, {"term": "Latency / jitter / loss", "short": "Delay / delay variation / never arrives."}, {"term": "Strong signal, poor Wi-Fi", "short": "Saturation: add APs."}]}, {"type": "term_set", "heading": "Tools", "terms": [{"term": "ping / traceroute", "short": "Reachable? / where it breaks."}, {"term": "nslookup, dig", "short": "DNS answers."}, {"term": "arp / netstat", "short": "IP to MAC / local ports."}, {"term": "nmap / Wireshark", "short": "Hosts and ports / packet contents."}, {"term": "TDR / OTDR", "short": "Copper / fiber distance to fault."}]}, {"type": "scenario", "prompt": "Choppy VoIP with plenty of bandwidth most likely points to what?", "choices": [{"id": "a", "text": "Packet loss from cabling"}, {"id": "b", "text": "Jitter"}, {"id": "c", "text": "Low throughput"}, {"id": "d", "text": "DNS"}], "answer": "b", "why": "Inconsistent delay ruins real-time audio."}, {"type": "scenario", "prompt": "Which step comes right after testing a confirmed theory?", "choices": [{"id": "a", "text": "Document"}, {"id": "b", "text": "Establish a plan of action"}, {"id": "c", "text": "Verify functionality"}, {"id": "d", "text": "Identify the problem"}], "answer": "b", "why": "Plan the fix and consider its effects."}, {"type": "scenario", "prompt": "Which tool shows open ports across many hosts on a subnet?", "choices": [{"id": "a", "text": "netstat"}, {"id": "b", "text": "nmap"}, {"id": "c", "text": "arp"}, {"id": "d", "text": "ipconfig"}], "answer": "b", "why": "nmap scans networks for hosts and ports."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = '97fa3df7-b8ac-4d0b-b147-20d49b255250';
